// Build an InstancedMesh from a list of {x,y,z,ry,s,sy?,tilt?,color?}
function instanced(geo, mat, items, { shadow = true, receive = true } = {}) {
    const mesh = new THREE.InstancedMesh(geo, mat, Math.max(1, items.length));
    const d = new THREE.Object3D();
    items.forEach((it, i) => {
        d.position.set(it.x, it.y, it.z);
        d.rotation.set(it.tx || 0, it.ry || 0, it.tz || 0);
        d.scale.set(it.s, it.sy || it.s, it.s);
        d.updateMatrix();
        mesh.setMatrixAt(i, d.matrix);
        if (it.color) mesh.setColorAt(i, it.color);
    });
    mesh.count = items.length;
    mesh.castShadow = shadow; mesh.receiveShadow = receive;
    mesh.frustumCulled = false;
    return mesh;
}

