// Screen size. The home-screen (standalone) iPhone app can report a stale, too-short window height after
// rotating — that left a black bar along the bottom — so there the real screen size wins and the page is sized to it.
const STANDALONE = !!(navigator.standalone || (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches));
function viewWH() {
    let w = innerWidth, h = innerHeight;
    if (STANDALONE && /iPhone|iPod|iPad/.test(navigator.userAgent) && screen.width && screen.height) {
        const L = Math.max(screen.width, screen.height), s = Math.min(screen.width, screen.height);
        const land = (typeof window.orientation === 'number') ? Math.abs(window.orientation) === 90 : w > h;
        w = land ? L : s; h = land ? s : L;
    }
    return [w, h];
}
const VW = () => viewWH()[0], VH = () => viewWH()[1];
function fitPage() {
    if (!STANDALONE) return;
    const [w, h] = viewWH();
    [document.documentElement, document.body].forEach(el => { el.style.width = w + 'px'; el.style.height = h + 'px'; });
    document.body.style.position = 'relative';
}
