// Puffy low-poly clouds on a big ring that rides along with the camera and drifts slowly
const Clouds = {
    group: new THREE.Group(),
    build() {
        const mat = new THREE.MeshBasicMaterial({ vertexColors: true, fog: false, transparent: true, opacity: 0.97, depthWrite: false });
        const top = new THREE.Color(0xffffff), bot = new THREE.Color(0xbfcad6), hor = new THREE.Color(CONFIG.world.skyHorizon), c = new THREE.Color();
        for (let i = 0; i < 34; i++) {
            const puffs = 4 + Math.floor(rand() * 5), base = rr(26, 46), parts = [];
            for (let k = 0; k < puffs; k++) {
                const b = blobGeo(base * rr(0.6, 1.15), rr(1.1, 1.5), rr(0.6, 0.8), rr(0.9, 1.25), 0.2, 9);
                const mid = 1 - Math.abs(k - (puffs - 1) / 2) / puffs;                       // taller in the middle
                b.translate((k - (puffs - 1) / 2) * base * 0.95 + rr(-8, 8), base * 0.3 * mid + rr(0, 6), rr(-base * 0.45, base * 0.45));
                parts.push(paint(b, 0xffffff, 0));
            }
            const geo = mergeGeos(parts), p = geo.attributes.position, cl = geo.attributes.color;
            geo.computeBoundingBox();
            const y0 = geo.boundingBox.min.y, y1 = geo.boundingBox.max.y;
            const a = rand() * Math.PI * 2, dist = rr(700, 1500), h = rr(230, 470), haze = 1 - smoothstep(0.14, 0.5, h / dist);
            for (let v = 0; v < p.count; v++) {
                c.copy(bot).lerp(top, smoothstep(y0, y0 + (y1 - y0) * 0.65, p.getY(v))).lerp(hor, haze * 0.55);
                cl.setXYZ(v, c.r, c.g, c.b);
            }
            const m = new THREE.Mesh(geo, mat);
            m.position.set(Math.cos(a) * dist, h, Math.sin(a) * dist);
            m.rotation.y = rand() * Math.PI; m.scale.setScalar(rr(0.8, 1.6));
            m.frustumCulled = false; m.renderOrder = -0.5;
            this.group.add(m);
        }
        scene.add(this.group);
    },
    update(delta) {
        this.group.position.set(camera.position.x, 0, camera.position.z);
        this.group.rotation.y += delta * 0.004;
    },
};

