// Soft sky/ground reflection map so the truck's paint, chrome and glass actually shine
const SKY_ENV = (() => {
    const es = new THREE.Scene();
    const geo = new THREE.SphereGeometry(10, 32, 16), p = geo.attributes.position, col = [], c = new THREE.Color();
    const top = new THREE.Color(CONFIG.world.skyTop), hor = new THREE.Color(CONFIG.world.skyHorizon), gnd = new THREE.Color(0x5d6a3c);
    for (let i = 0; i < p.count; i++) {
        const y = p.getY(i) / 10;
        if (y >= 0) c.copy(hor).lerp(top, Math.pow(y, 0.6)); else c.copy(hor).lerp(gnd, Math.min(1, -y * 4));
        col.push(c.r, c.g, c.b);
    }
    geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
    es.add(new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide })));
    const sunBall = new THREE.Mesh(new THREE.SphereGeometry(0.9, 12, 8), new THREE.MeshBasicMaterial({ color: 0xfff4dc }));
    sunBall.position.set(4, 7, 3); es.add(sunBall);
    const pm = new THREE.PMREMGenerator(renderer);
    const tex = pm.fromScene(es, 0.02).texture;
    pm.dispose();
    return tex;
})();
