    const P = CONFIG.site.pad, D = CONFIG.site.drive;
    if (x > P.x0 - margin && x < P.x1 + margin && z > P.z0 - margin && z < P.z1 + margin) return true;
    return x > D.x0 - margin && x < D.x1 + margin && z > P.z1 - 1 && z < D.z1 + margin;
