    let h = (fbm(x * 0.0035 + 10, z * 0.0035 - 4, 3) - 0.5) * 7.5     // broad swells
          + (noise2(x * 0.03, z * 0.03) - 0.5) * 0.5                   // small field lumps
          + hillField(x, z);
