// the dirt spur: same road surface as the farm road, curving off it up to the substation gate
function buildSpur() {
    const tex = dirtRoadTexture(), P = SPUR.pts, across = 6, hw = SPUR.hw, pos = [], uv = [], idx = [];
    let run = 0;
    P.forEach((p, i) => {
        if (i) run += Math.hypot(p.x - P[i - 1].x, p.z - P[i - 1].z);
        const a = P[Math.max(0, i - 1)], b = P[Math.min(P.length - 1, i + 1)], dx = b.x - a.x, dz = b.z - a.z, l = Math.hypot(dx, dz) || 1, nx = -dz / l, nz = dx / l;
        for (let j = 0; j <= across; j++) {
            const s = (j / across - 0.5) * 2 * hw, px = p.x + nx * s, pz = p.z + nz * s;
            pos.push(px, getTerrainHeight(px, pz) + 0.14, pz); uv.push(j / across, run / (hw * 2.2));
        }
    });
    for (let i = 0; i < P.length - 1; i++) for (let j = 0; j < across; j++) { const a = i * (across + 1) + j, b = a + across + 1; idx.push(a, b, a + 1, a + 1, b, b + 1); }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
    geo.setIndex(idx); geo.computeVertexNormals();
    const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ map: tex, roughness: 1, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3 }));
    mesh.receiveShadow = true;
    return mesh;
}

// ---- runtime: doors, roof cut-away, camera vs walls, microwaves, generator ----
// Which conex interior (if any) a world point is inside
function conexAt(x, y, z, grow = 0) {
    const { L, W, t, H } = CONEX;
    for (const cx of SITE.conexes) {
        const dx = x - cx.x, dz = z - cx.z, c = Math.cos(cx.yaw), s = Math.sin(cx.yaw);
        const lx = dx * c - dz * s, lz = dx * s + dz * c;
        if (Math.abs(lx) < L / 2 - t + grow && Math.abs(lz) < W / 2 - t + grow && y > cx.y - 1 && y < cx.y + H) return cx;
    }
    return null;
}
// Shorten the third-person camera so it never ends up inside a wall.
// Inside a box: stay within its walls (roof is cut away). Outside: stop in front of the walls.
function siteCameraDist(focus, dir, dist) {
    const { L, W, t, H } = CONEX;
    for (const cx of SITE.conexes) {
        if (!cx.group.visible) continue;
        const c = Math.cos(cx.yaw), s = Math.sin(cx.yaw);
        const dx = focus.x - cx.x, dz = focus.z - cx.z;
        const fx = dx * c - dz * s, fz = dx * s + dz * c, fy = focus.y - cx.y;
        const ux = dir.x * c - dir.z * s, uz = dir.x * s + dir.z * c, uy = dir.y;
        const inside = Math.abs(fx) < L / 2 - t && Math.abs(fz) < W / 2 - t && fy > 0 && fy < H + 3;
        if (inside) {
            const ex = ux > 1e-6 ? (L / 2 - t - fx) / ux : ux < -1e-6 ? (-L / 2 + t - fx) / ux : Infinity;
            const ez = uz > 1e-6 ? (W / 2 - t - fz) / uz : uz < -1e-6 ? (-W / 2 + t - fz) / uz : Infinity;
            dist = Math.min(dist, Math.max(0.6, Math.min(ex, ez) - 0.4));
        } else {
            // slab test against the outside of the box
            let t0 = 0, t1 = dist;
            const slab = (o, u, lo, hi) => {
                if (Math.abs(u) < 1e-6) return o >= lo && o <= hi;
                let a = (lo - o) / u, b = (hi - o) / u; if (a > b) [a, b] = [b, a];
                t0 = Math.max(t0, a); t1 = Math.min(t1, b); return t0 <= t1;
            };
            if (slab(fx, ux, -L / 2 - 0.3, L / 2 + 0.3) && slab(fz, uz, -W / 2 - 0.3, W / 2 + 0.3) && slab(fy, uy, -1, H + 0.4) && t0 > 0.01)
                dist = Math.min(dist, Math.max(0.9, t0 - 0.3));
        }
    }
    return dist;
}
function setRoofHidden(cx, hidden) {
    if (cx.roofHidden === hidden) return;
    cx.roofHidden = hidden;
    Object.values(cx.roofMats).forEach(m => { m.colorWrite = !hidden; m.depthWrite = !hidden; m.needsUpdate = true; });
}
function toggleDoor(d) {
    d.open = !d.open;
    SFX.door(d.open);
}
function updateSite(delta, now) {
    // doors swing toward open/closed; their collider follows the leaf
    SITE.conexes.forEach(cx => {
        const d = cx.door;
        // auto-open: swings open while anyone (you or a crewmate) is at the doorway, shuts again behind them
        let near = false;
        if (Ctl.autoDoors && d.world) {
            const close = q => q && Math.abs(q.y - (cx.y + CONEX.F)) < 4 && flatDist(q, d.world) < 5.5;
            near = !S.vehicle && close(playerGroup.position);
            if (!near && Net.on) Net.remotes.forEach(R => { if (!near && R.pos && !R.veh && close(R.pos)) near = true; });
        }
        if (near !== !!d.auto) { d.auto = near; if (!d.open) SFX.door(near); }
        const target = d.open || d.auto ? d.openAngle : 0;
        d.angle += (target - d.angle) * Math.min(1, delta * 7);
        d.pivot.rotation.y = d.angle;
        const p = localToWorldXZ(cx.x, cx.z, cx.yaw, d.hingeX + Math.cos(d.angle) * d.half, d.hingeZ - Math.sin(d.angle) * d.half);
        d.box.cx = p.x; d.box.cz = p.z; Boxes.setYaw(d.box, cx.yaw + d.angle);
    });
    // roof + ceiling vanish while you're inside, so the camera can look in
    const pp = playerGroup.position, inside = S.vehicle ? null : conexAt(pp.x, pp.y + 1, pp.z, 0.4);
    SITE.conexes.forEach(cx => setRoofHidden(cx, cx === inside));
    SITE.upper.group.visible = inside !== SITE.office;                  // inside the lower office: lift the whole upper box away so you can see in
    Ambience.update(!!inside);
    // microwaves
    SITE.micros.forEach(m => {
        if (!m.done && now >= m.until) { m.done = true; m.light.visible = false; SFX.ding(); showToast('DING! Lunch is hot. 🍔'); }
    });
    // generator: idle exhaust puffs + hum that fades with distance
    Site.genAcc = (Site.genAcc || 0) + delta * 3;
    while (Site.genAcc >= 1) { Site.genAcc -= 1; Smoke.emit(SITE.genStack, V(rr(-0.3, 0.3), rr(1.4, 2.2), rr(-0.3, 0.3)), 0x6d6d6d); }
    const ear = S.vehicle ? S.vehicle.group.position : playerGroup.position;      // measured from you, not the camera
    SFX.updateHum(Math.hypot(ear.x - (CONFIG.site.generator.x + 1.6), ear.z - CONFIG.site.generator.z) - 3);   // ~distance to the generator's side
}
const Site = { genAcc: 0 };

