        c.fillStyle = 'rgba(214,226,232,0.35)'; c.fillRect(0, 50, w, 3); c.fillRect(50, 0, 3, h);
        c.fillStyle = 'rgba(120,150,110,0.35)'; c.fillRect(0, 8, w, 3); c.fillRect(8, 0, 3, h);
