// =====================================================================================================
// [FORKLIFT]  Two little warehouse forklifts for Becky's delivery job (drive like the UTV; forks lift / drop a box)
// =====================================================================================================
function buildForklift(name, label, spawn, bodyHex) {
    const g = new THREE.Group();
    const M = {
        body: new THREE.MeshStandardMaterial({ color: bodyHex, roughness: 0.5, metalness: 0.15 }),
        black: new THREE.MeshStandardMaterial({ color: 0x1c1d1f, roughness: 0.7 }),
        steel: new THREE.MeshStandardMaterial({ color: 0x3b3f44, roughness: 0.45, metalness: 0.6 }),
        tire: new THREE.MeshStandardMaterial({ color: 0x111214, roughness: 0.95 }),
        rim: new THREE.MeshStandardMaterial({ color: 0xd8d4c8, roughness: 0.5, metalness: 0.3 }),
        seat: new THREE.MeshStandardMaterial({ color: 0x24262a, roughness: 0.8 }),
        amber: new THREE.MeshBasicMaterial({ color: 0xffa21a }),
    };
    const box = (w, h, d, m, x, y, z, par = g) => { const o = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); o.position.set(x, y, z); o.castShadow = true; par.add(o); return o; };
    // body: chassis, counterweight, step, dash
    box(3.7, 1.5, 4.6, M.body, 0, 1.55, -0.4);
    box(3.9, 2.5, 1.5, M.black, 0, 2.05, -3.05);                           // counterweight
    box(3.5, 0.5, 1.4, M.black, 0, 3.4, -3.05);
    box(3.8, 0.16, 4.2, M.black, 0, 2.37, -0.4);                          // floor plate
    box(1.6, 1.2, 0.8, M.body, 0, 2.95, 1.25);                            // dash / hood
    // overhead guard: 4 posts + a slatted roof
    [[1.75, 1.15], [-1.75, 1.15], [1.75, -2.55], [-1.75, -2.55]].forEach(([x, z]) => box(0.16, 5.4, 0.16, M.black, x, 5.0, z));
    box(3.8, 0.14, 3.9, M.black, 0, 7.7, -0.7);
    for (let k = -1; k <= 1; k++) box(0.08, 0.1, 3.8, M.steel, k * 1.1, 7.82, -0.7);
    const beacon = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.35, 10), M.amber); beacon.position.set(-1.3, 7.95, -2.3); g.add(beacon);
    // seat + steering
    box(1.6, 0.4, 1.4, M.seat, 0, 2.75, -1.25); const bk = box(1.6, 1.6, 0.3, M.seat, 0, 3.6, -2.0); bk.rotation.x = -0.15;
    const steeringWheel = new THREE.Mesh(new THREE.TorusGeometry(0.42, 0.07, 6, 14), M.black);
    steeringWheel.position.set(0, 4.1, 0.75); steeringWheel.rotation.x = -0.6; g.add(steeringWheel);
    box(0.12, 0.9, 0.12, M.steel, 0, 3.6, 0.95).rotation.x = -0.6;
    // wheels: big drive wheels up front, steer wheels at the back
    const wheels = [], frontPivots = [];
    const wheel = (x, z, r, steer) => {
        const piv = new THREE.Group(); piv.position.set(x, r, z); g.add(piv);
        const w = new THREE.Group(); piv.add(w);
        const t = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 0.75, 16), M.tire); t.rotation.z = Math.PI / 2; t.castShadow = true; w.add(t);
        const h = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.55, r * 0.55, 0.78, 10), M.rim); h.rotation.z = Math.PI / 2; w.add(h);
        wheels.push(w); if (steer) frontPivots.push(piv);
    };
    wheel(1.75, 1.5, 1.0, false); wheel(-1.75, 1.5, 1.0, false); wheel(1.6, -2.4, 0.75, true); wheel(-1.6, -2.4, 0.75, true);
    // mast (two uprights) + the carriage that rides up and down with the forks
    [-1.15, 1.15].forEach(x => box(0.3, 7.0, 0.4, M.steel, x, 3.9, 2.35));
    box(2.6, 0.25, 0.35, M.steel, 0, 7.3, 2.35); box(2.6, 0.25, 0.35, M.steel, 0, 0.7, 2.35);
    const forks = new THREE.Group(); forks.position.set(0, 0.45, 2.65); g.add(forks);
    box(3.0, 0.22, 0.2, M.black, 0, 0.15, 0, forks); box(3.0, 0.22, 0.2, M.black, 0, 1.5, 0, forks); box(3.0, 0.22, 0.2, M.black, 0, 2.6, 0, forks);
    [-1.4, -0.47, 0.47, 1.4].forEach(x => box(0.14, 2.6, 0.14, M.black, x, 1.35, 0, forks));                  // load backrest
    [-0.85, 0.85].forEach(x => { box(0.32, 1.2, 0.16, M.steel, x, 0.55, 0.05, forks); box(0.32, 0.14, 3.7, M.steel, x, 0, 1.9, forks); });   // forks
    const exhaust = box(0.18, 1.1, 0.18, M.black, -1.5, 3.9, -3.3);
    void exhaust;
    const cfg = {
        label, bonk: "BONK! Easy — that's Becky's forklift.",
        accel: 20, maxSpeed: 20, boostSpeed: 26, reverseMax: 12, turnRate: 2.3, coast: 0.05, bounce: 0.25,
        halfX: 2.05, halfZ: 4.6, centerZ: 0.8,
        wheelX: 1.7, wheelF: 1.5, wheelR: -2.4, wheelSpin: 0.9,
        seat: { x: 0, y: 0.32, z: -1.15 }, door: [3.4, -0.9], camHeight: 5.6,
        exhaust: [-1.5, 4.5, -3.3],
        engine: { bank: 'utv', vol: 0.16, idle: 1050, redline: 4800, crank: 0.5, cvt: true,
                  layers: [['utv_1150_off', 1150, 0], ['utv_3000_off', 3000, 0], ['utv_3000_on', 3000, 1], ['utv_5400_off', 5400, 0], ['utv_5400_on', 5400, 1]] },
        smoke: 0x6f6f6f, spawn, fuelRange: 40000,
    };
    return { name, cfg, group: g, wheels, frontPivots, steeringWheel, forks, forklift: true, carry: -1, forkH: 0.45, beacon, speed: 0, pitch: 0, roll: 0 };
}

