        const mid = { x: (P[0].x + P[1].x) / 2, z: (P[0].z + P[1].z) / 2 }, n0 = nrm(P[0], P[1]);
        const sgn = Dozer.inside(P, mid.x + n0.x * 0.5, mid.z + n0.z * 0.5) ? 1 : -1;
