            const mx = (n1.x + n2.x) * sgn, mz = (n1.z + n2.z) * sgn, k = 1 + n1.x * n2.x + n1.z * n2.z;
            let ox = mx / Math.max(k, 0.0001) * d, oz = mz / Math.max(k, 0.0001) * d; const L = Math.hypot(ox, oz);
