        const x0 = SUBZONE.x0 - margin, x1 = SUBZONE.x1 + margin, z0 = SUBZONE.z0 - margin, z1 = SUBZONE.z1 + margin, S = 14;
        const kept = []; for (let i = 0; i < n; i++) { const p = src[i]; if (!(p.x > x0 - S && p.x < x1 + S && p.z > z0 - S && p.z < z1 + S)) kept.push(i); }
        if (kept.length < 3) return null;
