            for (const r of [0, 3, 6, 9, 13]) for (let k = 0; k < 8; k++) { const x = p.x + Math.cos(k * 0.785) * r, z = p.z + Math.sin(k * 0.785) * r; if (Colliders.isFree(x, z, 2.4)) return { x, z }; }
