    const tb = (w, h, d, mat, x, y, z, p = torso) => box(w, h, d, mat, x, y - PY, z - PZ, p);
    box(2.6, 2.5, 2.5, mats.fur, 0, 2.95, -2.15);                                  // hindquarters
    box(2.2, 0.6, 3.4, mats.dark, 0, 1.75, -0.7);                                  // belly
