    tb(3.0, 2.3, 1.8, mats.light, 0, 3.65, 1.5);                                   // shoulder hump
    const head = new THREE.Group(); head.position.set(0, 3.45 - PY, 3.2 - PZ); torso.add(head);
    box(1.7, 1.5, 1.6, mats.fur, 0, 0, 0.1, head);                                 // skull
    box(0.95, 0.75, 1.1, mats.muzzle, 0, -0.35, 1.05, head);                       // muzzle
    box(0.42, 0.26, 0.22, mats.nose, 0, -0.02, 1.62, head);
    const jaw = box(0.85, 0.22, 0.95, mats.dark, 0, -0.78, 0.95, head);            // lower jaw (drops when it roars)
    [-0.2, 0.2].forEach(x => box(0.08, 0.2, 0.08, mats.tooth, x, -0.58, 1.38, head));
    [-1, 1].forEach(sd => {
        box(0.42, 0.42, 0.26, mats.dark, sd * 0.68, 0.88, -0.2, head);             // ears
        box(0.18, 0.14, 0.06, mats.eye, sd * 0.52, 0.25, 0.9, head);               // eyes
    });
    const mkLeg = (x, y, z, parent, bear2) => {
        const hip = new THREE.Group(); hip.position.set(x, y, z); parent.add(hip);
        box(1.0, 2.1, 1.1, mats.dark, 0, -1.05, 0, hip);
        box(1.06, 0.34, 1.3, mats.dark, 0, -2.15, 0.12, hip);
        [-0.3, 0, 0.3].forEach(cx => box(0.1, 0.1, 0.4, mats.claw, cx, -2.2, 0.82, hip));
        return hip;
    };
    const legs = [mkLeg(-1.0, 2.3 - PY, 1.1 - PZ, torso), mkLeg(1.0, 2.3 - PY, 1.1 - PZ, torso), mkLeg(-1.0, 2.3, -2.2, body), mkLeg(1.0, 2.3, -2.2, body)];
    const tail = box(0.4, 0.4, 0.3, mats.dark, 0, 3.3, -3.45);
    g.traverse(o => { if (o.isMesh) o.castShadow = true; });
    const bar = new THREE.Group();
    const bg = new THREE.Mesh(BOAR_BAR_GEO, BOAR_BAR_BG); bg.scale.set(3.6, 0.46, 1);
    const fill = new THREE.Mesh(BOAR_BAR_GEO, new THREE.MeshBasicMaterial({ color: 0xf97316, depthWrite: false })); fill.scale.set(3.4, 0.3, 1); fill.position.z = 0.01;
    bg.renderOrder = 5; fill.renderOrder = 6;
