            const sp = d.speed, run = d.state === 'flee' && sp > 8;
            d.phase += delta * (run ? 9 : sp * 1.6);
            const sw = Math.sin(d.phase);
            if (run) { d.legs.forEach((l, i) => { l.rotation.x = (i < 2 ? -1 : 1) * sw * 0.7; }); d.body.position.y = Math.max(0, Math.sin(d.phase)) * 1.1; d.body.rotation.x = -Math.cos(d.phase) * 0.15; }
            else { const a = Math.min(0.5, sp * 0.12); d.legs[0].rotation.x = sw * a; d.legs[3].rotation.x = sw * a; d.legs[1].rotation.x = -sw * a; d.legs[2].rotation.x = -sw * a; d.body.position.y = 0; d.body.rotation.x = 0; }
            const headDown = d.state === 'graze' ? 1 : 0;
            d.neck.rotation.x += ((headDown ? 1.5 : run ? 0.3 : d.state === 'alert' ? -0.2 : 0.1) - d.neck.rotation.x) * Math.min(1, delta * 4);
