                this.inside = u; u.occ = true; this.phase = 0; u.want = 0; u.closeAt = 0;
                this.camWas = { yaw: cam.yaw, pitch: cam.pitch }; cam.yaw = u.yaw + Math.PI; cam.pitch = 0.08;      // first person, facing the door
