            const b = this.route[(i + 1) % this.route.length], len = Math.hypot(b.x - a.x, b.z - a.z);
            const s = { a, b, len, t0: t, walk: len / OSHA.speed, yaw: Math.atan2(b.x - a.x, b.z - a.z) };
            t += s.walk + OSHA.pause; return s;
