['hb-bag', 'ppe-chip'].forEach(id => { const b = $(id); b.addEventListener('click', e => { e.stopPropagation(); if (!S.caught) Inv.toggle(); }); b.addEventListener('mousedown', e => e.stopPropagation()); });
// drag hotbar items to rearrange them (mouse or finger); slots 1 + 2 (hands, rod) stay put
