        const lfo = ctx.createOscillator(); lfo.frequency.value = 23; const lg = ctx.createGain(); lg.gain.value = 0.5; lfo.connect(lg).connect(am.gain);
        const env = ctx.createGain(); env.gain.setValueAtTime(0.0001, t); env.gain.exponentialRampToValueAtTime(1.3 * vol, t + 0.04); env.gain.exponentialRampToValueAtTime(0.0001, t + 0.5);
        n.connect(f).connect(am).connect(env).connect(this.bus);
