        o.frequency.setValueAtTime(800, t); o.frequency.linearRampToValueAtTime(1300, t + 0.15); o.frequency.linearRampToValueAtTime(1000, t + 0.4); o.frequency.linearRampToValueAtTime(480, t + 0.75);
