            g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.32, t + 0.015); g.gain.setValueAtTime(0.32, t + len - 0.04); g.gain.exponentialRampToValueAtTime(0.0001, t + len);
            o.connect(g).connect(this.bus); o.start(t); lfo.start(t); o.stop(t + len + 0.02); lfo.stop(t + len + 0.02);
