SFX.init();
// critter + hit sounds: never stack — at most one of each every ~quarter second, however many hits / animals fire them
[['boarGrunt', 300], ['yip', 300], ['bearGrowl', 400], ['bearRoar', 400], ['boarHit', 150], ['playerHit', 300], ['boarDie', 200]].forEach(([k, ms]) => {
    const f = SFX[k]; if (typeof f !== 'function') return;
    SFX[k] = function (...args) { const n = performance.now(); this.gateAt = this.gateAt || {}; if (n - (this.gateAt[k] || 0) < ms) return; this.gateAt[k] = n; return f.apply(this, args); };
});

// =====================================================================
// Engines: sampled loops (synthesized offline from a firing-pulse + exhaust model, WAV data at the
// end of the file). Each vehicle crossfades rpm/load layers and pitch-shifts them to the live rpm.
// The truck shifts through an automatic; the UTV's CVT holds rpm while it pulls. Starter crank on entry.
// =====================================================================
const Engines = {
    volume: 50, bus: null, bufs: {}, loading: null, voices: new Map(),
    init() {
        try { const v = localStorage.getItem('surveySim.engVolume'); if (v !== null) this.volume = clamp(parseInt(v), 0, 100); } catch (e) { /* ignore */ }
        $('eng-vol').value = this.volume; $('out-eng-vol').value = this.volume + '%';
        $('eng-vol').addEventListener('input', e => {
            this.volume = parseInt(e.target.value); $('out-eng-vol').value = this.volume + '%';
            if (this.bus) this.bus.gain.setTargetAtTime(this.volume / 100, Music.ctx.currentTime, 0.05);
            try { localStorage.setItem('surveySim.engVolume', String(this.volume)); } catch (err) { /* ignore */ }
        });
    },
    ctx() {
        const ctx = Music.ctx; if (!ctx) return null;
        if (!this.bus) { this.bus = ctx.createGain(); this.bus.gain.value = this.volume / 100; this.bus.connect(ctx.destination); }
        if (!this.loading) this.loading = this.load(ctx);
        return ctx;
    },
    async load(ctx) {
        const ids = [];
        VEHICLES.forEach(v => { v.cfg.engine.layers.forEach(l => ids.push(l[0])); ids.push(v.cfg.engine.bank + '_start'); });
        await Promise.all(ids.map(async id => {
            try {
                const ab = await audioBytes('eng-' + id); if (!ab) return;
                this.bufs[id] = await decodeAudio(ctx, ab);
            } catch (e) { console.warn('engine sample failed', id, e); }
        }));
    },
    voice(v) {
        if (this.voices.has(v)) return this.voices.get(v);
        const ctx = this.ctx(); if (!ctx) return null;
        const E = v.cfg.engine;
        if (!E.layers.every(l => this.bufs[l[0]])) return null;          // still decoding
        const out = ctx.createGain(); out.gain.value = 0; out.connect(this.bus);
        const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 3000; lp.Q.value = 0.7; lp.connect(out);
        const layers = E.layers.map(([id, rpm, load]) => {
            const src = ctx.createBufferSource(); src.buffer = this.bufs[id]; src.loop = true;
            const g = ctx.createGain(); g.gain.value = 0; src.connect(g).connect(lp);
            src.start(0, Math.random() * src.buffer.duration);
            return { rpm, load, src, g };
        });
        let whine = null;
        if (E.cvt) {                                                      // CVT belt / clutch whine
            const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = 300;
            const g = ctx.createGain(); g.gain.value = 0; o.connect(g).connect(lp); o.start();
            whine = { o, g };
        }
        let pan = null;
        if (ctx.createStereoPanner) { pan = ctx.createStereoPanner(); out.disconnect(); out.connect(pan); pan.connect(this.bus); }
        const vc = { out, lp, layers, whine, pan };
        this.voices.set(v, vc);
        return vc;
    },
    // engine state lives on the vehicle so it works with or without audio
    start(v) {
        if (v.fuel <= 0) { v.engineState = 'off'; return; }
        v.engineState = 'starting'; v.runAt = performance.now() + v.cfg.engine.crank * 1000;
        v.rpm = 0; v.gear = 1; v.load = 0; v.shiftT = 0;
        const ctx = this.ctx(), buf = this.bufs[v.cfg.engine.bank + '_start'];
        if (ctx && buf) {
            const src = ctx.createBufferSource(); src.buffer = buf;
            const g = ctx.createGain(); g.gain.value = v.cfg.engine.vol * 1.1 * this.near(v).g; src.connect(g).connect(this.bus); src.start();
        }
    },
    stop(v) { v.engineState = 'off'; },
    // how loud a vehicle is from where I'm listening (the camera): full up close, gone past ~420 ft; pan = left/right
    near(v) {
        if (S.vehicle === v) return { g: 1, pan: 0 };
        const p = v.group.position, c = camera.position, dx = p.x - c.x, dz = p.z - c.z, d = Math.hypot(dx, dz);
        const k = clamp(1 - (d - 30) / 390, 0, 1), g = k * k;
        const fx = -Math.sin(cam.yaw), fz = -Math.cos(cam.yaw);         // camera forward on the ground
        const side = d > 1 ? (dx * -fz + dz * fx) / d : 0;               // + = to my right
        return { g, pan: clamp(side * 0.75, -0.75, 0.75) };
    },
    // true when the engine can make power (undefined = never started via the door, e.g. debug)
    running(v) { return v.engineState === 'running' || v.engineState === undefined; },
    // rpm + load model
    simulate(v, delta) {
        const E = v.cfg.engine, spd = Math.abs(v.speed), th = S.vehicle === v && !S.pass ? (v.throttle || 0) : v.remoteBy ? (v.remoteTh || 0) : 0;
        if (v.engineState === 'starting' && performance.now() >= v.runAt) { v.engineState = 'running'; v.rpm = E.idle * 1.6; }
        if (v.rpm === undefined) { v.rpm = E.idle; v.gear = 1; v.load = 0; v.shiftT = 0; }
        let target;
        if (v.engineState === 'off' || v.engineState === 'starting') target = 0;
        else if (E.gears) {                                               // automatic gearbox
            let g = 1; while (g < E.gears.length - 1 && spd > E.gears[g]) g++;
            if (g !== v.gear) { v.shiftT = 0.28; v.gear = g; }
            const lo = E.gears[g - 1], hi = E.gears[g], f = clamp((spd - lo) / (hi - lo), 0, 1);
            const band = E.redline * 0.8 - E.idle;
            target = E.idle + band * (g === 1 ? f * 0.85 : 0.34 + 0.6 * f) + th * (spd < 6 ? 900 : 260);
        } else {                                                          // CVT: revs up and holds while pulling
            target = th > 0.05 ? E.idle + (E.redline * 0.72 - E.idle) * (0.45 + 0.55 * th) * (0.7 + 0.3 * Math.min(1, spd / 30)) : E.idle + spd * 30;
        }
        v.shiftT = Math.max(0, (v.shiftT || 0) - delta);
        const rate = target > v.rpm ? (v.shiftT > 0 ? 3 : 7) : (v.shiftT > 0 ? 14 : 3.5);
        v.rpm += (target - v.rpm) * Math.min(1, delta * rate);
        const loadT = this.running(v) && th > 0.05 ? (0.35 + 0.65 * th) * (v.shiftT > 0 ? 0.3 : 1) : 0;
        v.load += (loadT - v.load) * Math.min(1, delta * 6);
    },
    update(delta) {
        VEHICLES.forEach(v => this.simulate(v, delta));
        const ctx = Music.ctx; if (!ctx) return;
        this.ctx();
        const t = ctx.currentTime;
        VEHICLES.forEach(v => {
            const live = v.engineState === 'running' || (v.engineState === undefined && S.vehicle === v);
            if (!live && !this.voices.has(v)) return;
            const vc = this.voice(v); if (!vc) return;
            const E = v.cfg.engine, r = Math.max(v.rpm, 1), ld = v.load || 0;
            const near = this.near(v);                                   // distance falloff: someone else's UTV across the map is silent
            if (vc.pan) vc.pan.pan.setTargetAtTime(S.vehicle === v ? 0 : near.pan, t, 0.1);
            const lv = [E.layers[0][1], E.layers[1][1], E.layers[3][1]];
            let w0 = 0, w1 = 0, w2 = 0;
            if (r <= lv[1]) { const k = clamp((r - lv[0]) / (lv[1] - lv[0]), 0, 1); w0 = Math.cos(k * Math.PI / 2); w1 = Math.sin(k * Math.PI / 2); }
            else { const k = clamp((r - lv[1]) / (lv[2] - lv[1]), 0, 1); w1 = Math.cos(k * Math.PI / 2); w2 = Math.sin(k * Math.PI / 2); }
            const on = Math.sqrt(ld), off = Math.sqrt(1 - ld);
            const weights = [w0, w1 * off, w1 * on, w2 * off, w2 * on];
            vc.layers.forEach((L, i) => {
                L.g.gain.setTargetAtTime(weights[i], t, 0.06);
                L.src.playbackRate.setTargetAtTime(clamp(r / L.rpm, 0.45, 2.2), t, 0.05);
            });
            vc.lp.frequency.setTargetAtTime((1600 + 5200 * ld + r * 0.4) * (0.3 + 0.7 * near.g), t, 0.08);
            if (vc.whine) {
                const spd = Math.abs(v.speed);
                vc.whine.o.frequency.setTargetAtTime(240 + spd * 16 + r * 0.03, t, 0.1);
                vc.whine.g.gain.setTargetAtTime(live ? 0.035 * Math.min(1, spd / 12) * (0.5 + 0.5 * ld) : 0, t, 0.15);
            }
            vc.out.gain.setTargetAtTime(live ? E.vol * near.g : 0, t, live ? 0.08 : 0.35);
        });
    },
};
Engines.init();

// =====================================================================
// [SMOKE]  Exhaust puffs: pooled soft sprites, thicker on throttle
// =====================================================================
const Smoke = {
    pool: [], live: [], acc: new Map(),
    init() {
        const cv = document.createElement('canvas'); cv.width = cv.height = 64;
        const c = cv.getContext('2d'), gr = c.createRadialGradient(32, 32, 2, 32, 32, 31);
        gr.addColorStop(0, 'rgba(255,255,255,0.95)'); gr.addColorStop(0.5, 'rgba(255,255,255,0.45)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
        c.fillStyle = gr; c.fillRect(0, 0, 64, 64);
        const tex = new THREE.CanvasTexture(cv);
        for (let i = 0; i < 120; i++) {
            const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, opacity: 0 }));
            sp.visible = false; scene.add(sp); this.pool.push(sp);
        }
    },
    emit(pos, vel, color, size, life) {
        const sp = this.pool.pop(); if (!sp) return;
        sp.position.copy(pos); sp.visible = true; sp.material.color.setHex(color);
        this.live.push({ sp, vel, age: 0, life: life || rr(1.2, 2.0), size: size || rr(0.35, 0.55) });
    },
    update(delta) {
        // emit from the vehicle being driven
        const v = S.vehicle;
        if (v && v.fuel > 0 && Engines.running(v)) {
            const rate = 7 + 45 * (v.throttle || 0) + Math.abs(v.speed) * 0.4;     // puffs per second
            let acc = (this.acc.get(v) || 0) + rate * delta;
            const tip = v.group.localToWorld(V(...v.cfg.exhaust));
            const back = V(0, 0, -1).applyQuaternion(v.group.quaternion);
            while (acc >= 1) {
                acc -= 1;
                const vel = back.clone().multiplyScalar(rr(1.5, 3) + (v.throttle || 0) * 2).add(V(rr(-0.4, 0.4), rr(0.6, 1.3), rr(-0.4, 0.4)));
                this.emit(tip, vel, v.cfg.smoke);
            }
            this.acc.set(v, acc);
        }
        for (let i = this.live.length - 1; i >= 0; i--) {
            const p = this.live[i];
            p.age += delta;
            const t = p.age / p.life;
            if (t >= 1) { p.sp.visible = false; p.sp.material.opacity = 0; this.pool.push(p.sp); this.live.splice(i, 1); continue; }
            p.sp.position.addScaledVector(p.vel, delta);
            p.vel.multiplyScalar(Math.pow(0.35, delta)); p.vel.y += 0.9 * delta;            // slow down, drift up
            p.sp.scale.setScalar(p.size * (1 + t * 3.5));
            p.sp.material.opacity = 0.42 * (1 - t) * Math.min(1, p.age * 8);
        }
    },
};
Smoke.init();

// =====================================================================
// [SYSTEMS]  per-frame updates
// =====================================================================
const _move = new THREE.Vector3();

// Sit a vehicle on the terrain: height + pitch/roll from its 4 wheel contact points
// =====================================================================
// [BUMPER]  Bumper cars: vehicles bounce off each other with a goofy rock-and-hop, and anything that rams a crewmate on foot
//           launches them (little damage). A vehicle that's shoved (parked, nobody in it) slides a bit.
// =====================================================================
// Call-of-Duty slide (Ctrl / SLIDE button): burst forward along your heading, body leans back with one leg
// kicked out in front, dust trails off your heels, friction scrapes. Ends in a quick stand-up.
const SLIDE = { dur: 1.4, boost: 1.7, minSpeed: 9, cooldown: 0.9, stamina: 8, steer: 0.5, tail: 1.15 };      // ~2x the old distance
const Slide = {
    active: false, t: 0, vx: 0, vz: 0, v0: 0, cd: 0, dust: 0,
    can() {
        return !this.active && this.cd <= 0 && !S.vehicle && !S.driving && !S.seat && !S.dead && !Mantle.active && !menusOpen() && rig.canJump && !S.miniGame;
    },
    try() {
        if (!this.can()) return false;
        const P = CONFIG.player, inZ = clamp((keys.w ? 1 : 0) - (keys.s ? 1 : 0) + joy.y, -1, 1), inX = clamp((keys.d ? 1 : 0) - (keys.a ? 1 : 0) + joy.x, -1, 1);
        let dx, dz, sp;
        if (Math.hypot(inX, inZ) > 0.08) {
            dx = -Math.sin(cam.yaw) * inZ + Math.cos(cam.yaw) * inX; dz = -Math.cos(cam.yaw) * inZ - Math.sin(cam.yaw) * inX;
            const m = Math.hypot(dx, dz) || 1; dx /= m; dz /= m;
            sp = (Combat.sprint ? P.sprint : P.walk * 1.15) * this.boostFor();
        } else { const y = playerGroup.rotation.y; dx = Math.sin(y); dz = Math.cos(y); sp = P.walk * 1.1; }       // standing still: a short skid forward
        if (!S.god) { if (S.exhausted) return false; S.stamina = Math.max(0, S.stamina - SLIDE.stamina); }
        this.active = true; this.t = 0; this.v0 = Math.max(SLIDE.minSpeed, sp * SLIDE.boost); this.vx = dx; this.vz = dz; this.dust = 0;
        playerGroup.rotation.y = Math.atan2(dx, dz);
        SFX.slide(); Pow.show(V(playerGroup.position.x, playerGroup.position.y + 5.2, playerGroup.position.z), 'SHWOOP!', false, 'hus');
        return true;
    },
    boostFor() { return 1; },
    // this frame's velocity (units/s): fast start, long friction tail
    vel() { const k = clamp(1 - this.t / SLIDE.dur, 0, 1); return this.v0 * Math.pow(k, SLIDE.tail); },
    advance(delta) {
        this.t += delta;
        if (this.t >= SLIDE.dur) { this.end(false); return { x: 0, z: 0 }; }
        // a little steering so you can bend the slide, not cartwheel it
        const P = playerGroup.position, inX = clamp((keys.d ? 1 : 0) - (keys.a ? 1 : 0) + joy.x, -1, 1);
        if (Math.abs(inX) > 0.2) { const a = -inX * SLIDE.steer * delta, c = Math.cos(a), s = Math.sin(a), x = this.vx * c - this.vz * s, z = this.vx * s + this.vz * c; this.vx = x; this.vz = z; playerGroup.rotation.y = Math.atan2(x, z); }
        const v = this.vel();
        if ((this.dust -= delta) <= 0) {
            this.dust = 0.045;
            Smoke.emit(V(P.x - this.vx * 1.2, P.y + 0.25, P.z - this.vz * 1.2), V(rr(-2.5, 2.5) - this.vx * 3, rr(1.5, 3.5), rr(-2.5, 2.5) - this.vz * 3), 0xc9b58f);
        }
        Shake.add(0.012);
        return { x: this.vx * v, z: this.vz * v };
    },
    end(hitWall) {
        if (!this.active) return;
        this.active = false; this.cd = SLIDE.cooldown;
        if (hitWall) { SFX.thud(); Shake.add(0.35); Pow.show(V(playerGroup.position.x, playerGroup.position.y + 4.5, playerGroup.position.z), 'OOF!'); }
    },
    update(delta) { if (this.cd > 0) this.cd -= delta; },
    // body language, blended in/out by weight so it never snaps: lean back, lead leg out straight, rear leg folded, arms trailing
    poseRig(r, delta, on) {
        r.slideW = (r.slideW || 0) + ((on ? 1 : 0) - (r.slideW || 0)) * Math.min(1, delta * (on ? 16 : 9));
        const w = r.slideW; if (w < 0.004) return;
        const to = (o, k, v) => { o.rotation[k] += (v - o.rotation[k]) * w; };
        r.pelvis.position.y -= 1.45 * w;
        to(r.spine, 'x', -0.62); r.spine.rotation.y *= (1 - w); r.spine.rotation.z *= (1 - w);
        to(r.legL.hip, 'x', -1.38); to(r.legL.knee, 'x', 0.05);
        to(r.legR.hip, 'x', -0.55); to(r.legR.knee, 'x', 1.9);
        to(r.armL.shoulder, 'x', -0.35); to(r.armL.shoulder, 'z', 0.7); to(r.armL.elbow, 'x', -0.5);
        to(r.armR.shoulder, 'x', 0.55); to(r.armR.shoulder, 'z', -0.7); to(r.armR.elbow, 'x', -0.3);
    },
};

// Double-tap jump (Space / JUMP) while holding a direction: a tuck-and-roll that way. Forward / back are somersaults,
// left / right are barrel rolls. The first tap's hop is cancelled, you drop to the ground and roll out.
const ROLL = { dur: 0.62, dist: 19, cooldown: 0.55, stamina: 6, window: 300 };
const Roll = {
    active: false, t: 0, vx: 0, vz: 0, peak: 0, kind: 'f', sgn: 1, cd: 0, lastTap: 0, dust: 0,
    can() { return !this.active && this.cd <= 0 && !Slide.active && !S.vehicle && !S.driving && !S.seat && !S.dead && !Mantle.active && !menusOpen() && !S.miniGame && !(S.exhausted && !S.god); },
    // call on every jump press: true if this press turned into a roll (so the jump should NOT happen)
    tap(now) {
        const dbl = now - this.lastTap < ROLL.window; this.lastTap = now;
        if (!dbl || !this.can()) return false;
        this.lastTap = 0; this.start(); return true;
    },
    start() {
        const inZ = clamp((keys.w ? 1 : 0) - (keys.s ? 1 : 0) + joy.y, -1, 1), inX = clamp((keys.d ? 1 : 0) - (keys.a ? 1 : 0) + joy.x, -1, 1);
        let dx, dz;
        if (Math.hypot(inX, inZ) > 0.15) {
            dx = -Math.sin(cam.yaw) * inZ + Math.cos(cam.yaw) * inX; dz = -Math.cos(cam.yaw) * inZ - Math.sin(cam.yaw) * inX;
            const m = Math.hypot(dx, dz) || 1; dx /= m; dz /= m;
        } else { const y = playerGroup.rotation.y; dx = Math.sin(y); dz = Math.cos(y); }          // no direction held: roll the way you face
        // which way is that relative to the body? (forward/back flip about X, left/right barrel about Z)
        const yaw = playerGroup.rotation.y, lf = dx * Math.sin(yaw) + dz * Math.cos(yaw), lr = -(dx * Math.cos(yaw) - dz * Math.sin(yaw));     // +lr = to the character's right
        if (Math.abs(lf) >= Math.abs(lr)) { this.kind = 'f'; this.sgn = lf >= 0 ? 1 : -1; } else { this.kind = 's'; this.sgn = lr >= 0 ? 1 : -1; }
        if (!S.god) S.stamina = Math.max(0, S.stamina - ROLL.stamina);
        this.active = true; this.t = 0; this.vx = dx; this.vz = dz; this.peak = ROLL.dist / (ROLL.dur * 0.78); this.dust = 0;
        if (!rig.canJump) rig.velY = Math.min(rig.velY, -34);                                      // cancel the hop: straight down, then roll out
        Net.dropGuard();
        SFX.slide(); Pow.show(V(playerGroup.position.x, playerGroup.position.y + 5.2, playerGroup.position.z), 'ROLL!', false, 'hus');
    },
    advance(delta) {
        this.t += delta;
        if (this.t >= ROLL.dur) { this.end(false); return { x: 0, z: 0 }; }
        const u = this.t / ROLL.dur, P = playerGroup.position, v = this.peak * (1 - 0.45 * u);
        if ((this.dust -= delta) <= 0) { this.dust = 0.07; Smoke.emit(V(P.x, P.y + 0.3, P.z), V(rr(-2, 2), rr(1, 2.6), rr(-2, 2)), 0xc9b58f); }
        return { x: this.vx * v, z: this.vz * v };
    },
    end(hitWall) {
        if (!this.active) return;
        this.active = false; this.cd = ROLL.cooldown; rig.pelvis.rotation.x = 0; rig.pelvis.rotation.z = 0;
        if (hitWall) { SFX.thud(); Shake.add(0.25); }
    },
    update(delta) { if (this.cd > 0) this.cd -= delta; },
    // spin the whole body about its middle (u = 0..1 through the roll); call after the walk pose. `r.rollW` blends it in/out.
    spin(r, u, kind, sgn) {
        const th = sgn * Math.PI * 2 * (u * u * (3 - 2 * u) * 0.5 + u * 0.5), cy = Goof.CY, hop = Math.sin(u * Math.PI) * 0.5;
        if (kind === 'f') Goof.tilt(r, th, hop);
        else { r.pelvis.rotation.z = th; r.pelvis.position.y += cy - cy * Math.cos(th) + hop; r.pelvis.position.x += cy * Math.sin(th); }
        const k = Math.sin(clamp(u * 1.15, 0, 1) * Math.PI);                                       // tuck: knees up, arms hugging in
        r.legL.hip.rotation.x = -1.5 * k; r.legR.hip.rotation.x = -1.5 * k; r.legL.knee.rotation.x = 1.9 * k; r.legR.knee.rotation.x = 1.9 * k;
        r.spine.rotation.x = 0.55 * k;
        r.armL.shoulder.rotation.set(-1.3 * k, 0, 0.3 * k); r.armR.shoulder.rotation.set(-1.3 * k, 0, -0.3 * k);
        r.armL.elbow.rotation.x = -1.7 * k; r.armR.elbow.rotation.x = -1.7 * k;
    },
    poseRig(r) { if (this.active) this.spin(r, this.t / ROLL.dur, this.kind, this.sgn); else if (r.pelvis.rotation.z) r.pelvis.rotation.z = 0; },
};

const Bump = {
    whipT: 99, whipAmt: 0,
    kick(v, amt) { v.kick = { t: 0, amt: clamp(amt, 0.2, 1.3), dir: v.speed >= 0 ? -1 : 1 }; },
    // the driver's head snaps back (applied after poseSeated)
    whip(amt) { this.whipT = 0; this.whipAmt = clamp(amt, 0.3, 1.2); },
    whipPose(rig, delta) {
        if (this.whipT > 0.8) return;
        this.whipT += delta;
        const e = Math.exp(-5 * this.whipT) * Math.sin(this.whipT * 24) * this.whipAmt;
        rig.spine.rotation.x += -0.45 * e; rig.head.rotation.x += -0.6 * e;
        rig.armL.shoulder.rotation.x += 0.35 * e; rig.armR.shoulder.rotation.x += 0.35 * e;
    },
    // one vehicle drove into another: both rock, hop and recoil; a parked one (nobody in it) gets shoved
    vehicles(v, other, sp) {
        const now = performance.now(); if (now < (v.bumpAt || 0)) return;
        v.bumpAt = now + 450;
        const g = v.group, sgn = Math.sign(v.speed) || 1;
        v.speed = -v.speed * 0.6 - sgn * 4;                          // thrown back a little
        this.kick(v, sp / 32);
        if (S.vehicle === v) { this.whip(sp / 30); Shake.add(clamp(sp / 40, 0.25, 0.8)); }
        const words = ['BUMP!', 'BOING!', 'HONK!', 'OOF!', 'BONK!'];
        Pow.show(V(g.position.x, g.position.y + 9, g.position.z), words[Math.floor(Math.random() * words.length)], true);
        SFX.bump(clamp(sp / 28, 0.45, 1));
        if (!other) return;
        other.kick = { t: 0, amt: clamp(sp / 30, 0.2, 1.3), dir: -sgn };
        if (!other.remoteBy && !Net.helping() && S.vehicle !== other) {   // a parked one slides away (the crew lead's phone decides where parked vehicles are)
            const dx = other.group.position.x - g.position.x, dz = other.group.position.z - g.position.z, d = Math.hypot(dx, dz) || 1;
            other.shove = { x: dx / d * Math.min(26, sp * 0.9), z: dz / d * Math.min(26, sp * 0.9), t: 0.55 };
        }
    },
    // per frame: apply kicks (rock + hop) and shoves on top of whatever the vehicle did this frame
    update(delta) {
        for (const v of VEHICLES) {
            const g = v.group, k = v.kick, sh = v.shove;
            if (sh) {
                g.position.x += sh.x * delta; g.position.z += sh.z * delta;
                sh.x *= Math.pow(0.03, delta); sh.z *= Math.pow(0.03, delta);
                resolveVehicleVsStatics(v);
                if ((sh.t -= delta) <= 0) v.shove = null;
            }
            if (!k && !sh) continue;
            if (S.vehicle !== v && !v.remoteBy) settleOnTerrain(v, 1);
            if (k) {
                k.t += delta; const u = k.t / 0.75;
                if (u >= 1) { v.kick = null; continue; }
                const decay = Math.exp(-4.5 * u), w = Math.sin(u * 26);
                g.rotation.x += k.dir * 0.2 * k.amt * decay * Math.cos(u * 15);
                g.rotation.z += 0.13 * k.amt * decay * w;
                g.position.y += Math.sin(Math.min(1, u * 2.4) * Math.PI) * 1.5 * k.amt;
                g.rotation.y += 0.035 * k.amt * decay * w;
            }
        }
    },
};

// =====================================================================
// [MANTLE]  Vault and climb: jump at the hood of a truck / UTV and you slide across it; jump at the cab or a conex wall
//           and you haul yourself up onto the roof. Roofs are real ground to stand and walk on.
// =====================================================================
const MANTLE = { reach: 3.4, climbMax: 11.8 };
const Mantle = {
    active: null, roofs: MANTLE_ROOFS,
    // nearest thing you can vault / climb, or null
    find() {
        const P = playerGroup.position, fy = playerGroup.rotation.y, fx = Math.sin(fy), fz = Math.cos(fy);
        let best = null, bd = 1e9;
        for (const v of VEHICLES) {
            const M = v.cfg.mantle; if (!M || S.vehicle === v) continue;
            const g = v.group, c = Math.cos(g.rotation.y), s = Math.sin(g.rotation.y), dx = P.x - g.position.x, dz = P.z - g.position.z;
            const lx = dx * c - dz * s, lz = dx * s + dz * c, hx = v.cfg.halfX, out = Math.abs(lx) - hx;
            if (Math.abs(P.y - g.position.y) > 2.6 || out < -0.5 || out > MANTLE.reach) continue;
            const sx = lx >= 0 ? 1 : -1, nx = -sx * c, nz = sx * s;                     // world direction from you into the vehicle's side
            if (fx * nx + fz * nz < 0.4) continue;
            for (const seg of M) {
                if (lz < seg.z0 - 0.4 || lz > seg.z1 + 0.4) continue;
                if (out < bd) {
                    bd = out;
                    const to = (tlx, tlz) => ({ x: g.position.x + tlx * c + tlz * s, z: g.position.z - tlx * s + tlz * c });
                    if (seg.kind === 'slide') {
                        const end = to(-sx * (hx + 2.4), lz);
                        best = { kind: 'slide', y: g.position.y + seg.y, sx: P.x, sz: P.z, tx: end.x, tz: end.z, ty: getTerrainHeight(end.x, end.z), dur: 0.72 };
                    } else {
                        const end = to(sx * (seg.shx - 0.9), clamp(lz, seg.sz0 + 0.8, seg.sz1 - 0.8));
                        best = { kind: 'climb', y: g.position.y + seg.y, sx: P.x, sz: P.z, tx: end.x, tz: end.z, ty: g.position.y + seg.y, dur: 0.8 + (seg.y - P.y) * 0.03, face: Math.atan2(nx, nz) };
                    }
                }
            }
        }
        for (const R of this.roofs) {
            const c = Math.cos(R.yaw), s = Math.sin(R.yaw), dx = P.x - R.cx, dz = P.z - R.cz, lx = dx * c - dz * s, lz = dx * s + dz * c;
            const out = Math.max(Math.abs(lx) - R.hx, Math.abs(lz) - R.hz), rise = R.y - P.y;
            if (out < -0.3 || out > MANTLE.reach || rise < 2 || rise > MANTLE.climbMax) continue;
            const qx = clamp(lx, -R.hx, R.hx), qz = clamp(lz, -R.hz, R.hz), wx = R.cx + qx * c + qz * s - P.x, wz = R.cz - qx * s + qz * c - P.z, wd = Math.hypot(wx, wz) || 1;
            if ((fx * wx + fz * wz) / wd < 0.5 && out > 0.6) continue;
            if (out < bd) {
                bd = out;
                const tx = clamp(lx, -R.hx + 1.6, R.hx - 1.6), tz = clamp(lz, -R.hz + 1.6, R.hz - 1.6);
                best = { kind: 'climb', y: R.y, sx: P.x, sz: P.z, tx: R.cx + tx * c + tz * s, tz: R.cz - tx * s + tz * c, ty: R.y, dur: 0.8 + rise * 0.045, face: Math.atan2(wx, wz) };
            }
        }
        return best;
    },
    try() {
        if (this.active || S.dead || S.vehicle || S.seat || menusOpen() || S.health <= 0) return false;
        const m = this.find(); if (!m) return false;
        m.t = 0; m.y0 = playerGroup.position.y;
        this.active = m; rig.velY = 0; rig.canJump = false; S.knock = null;
        playerGroup.rotation.y = m.kind === 'slide' ? Math.atan2(m.tx - m.sx, m.tz - m.sz) : m.face;
        if (m.kind === 'slide') { SFX.whee(); Pow.show(V(m.sx, m.y0 + 7, m.sz), 'SLIDE!'); } else { SFX.boing(); Pow.show(V(m.sx, m.y0 + 7, m.sz), 'UP WE GO!'); }
        return true;
    },
    cancel() {
        if (!this.active) return;
        this.active = null; rig.pelvis.rotation.x = 0; rig.velY = 0;
    },
    // drive the whole move; called from updatePlayer in place of walking
    step(delta) {
        const m = this.active, pos = playerGroup.position, r = rig;
        m.t += delta; const u = Math.min(1, m.t / m.dur), ss = (a, b, x) => smoothstep(a, b, x);
        poseWalk(r, delta, false, false, S.hasRtkRod && !S.rodSlung);
        r.pelvis.position.set(0, 0, 0);
        if (m.kind === 'slide') {
            const k = ss(0, 0.22, u) * (1 - ss(0.78, 1, u)), e = ss(0.1, 0.9, u);
            pos.x = m.sx + (m.tx - m.sx) * e; pos.z = m.sz + (m.tz - m.sz) * e;
            const lie = m.y - 2.6 + 0.3, hold = Math.max(m.y0, lie);
            pos.y = u < 0.5 ? m.y0 + (hold - m.y0) * ss(0, 0.22, u) : m.ty + (hold - m.ty) * (1 - ss(0.78, 1, u));
            Goof.tilt(r, -1.45 * k, 0);
            r.armL.shoulder.rotation.set(-2.9 * k, 0, 0.35 * k); r.armR.shoulder.rotation.set(-2.9 * k, 0, -0.35 * k);
            r.legL.hip.rotation.set(-0.15 * k, 0, 0.14 * k); r.legR.hip.rotation.set(-0.1 * k, 0, -0.14 * k);
            r.head.rotation.set(0.3 * k, 0, Math.sin(m.t * 18) * 0.12 * k);
            if (!m.dusted && u > 0.82) { m.dusted = true; for (let i = 0; i < 6; i++) Smoke.emit(V(pos.x, pos.y + 0.3, pos.z), V(rr(-2, 2), rr(0.5, 1.5), rr(-2, 2)), 0xb8ad94); }
        } else {
            const hang = m.ty - 4.4;                                                  // hands reach the edge when the feet are about here
            if (u < 0.42) {                                                           // jump + grab on
                const e = ss(0, 0.42, u);
                pos.x = m.sx; pos.z = m.sz; pos.y = m.y0 + (Math.max(m.y0, hang) - m.y0) * e;
                const kick = Math.sin(m.t * 22) * 0.7 * e;
                r.armL.shoulder.rotation.set(-2.95, 0, 0.18); r.armR.shoulder.rotation.set(-2.95, 0, -0.18);
                r.legL.hip.rotation.x = -0.5 + kick; r.legR.hip.rotation.x = -0.5 - kick; r.legL.knee.rotation.x = 0.8; r.legR.knee.rotation.x = 0.5;
                r.spine.rotation.x = 0.12 * e;
            } else if (u < 0.8) {                                                     // heave up and over, chest to the roof
                const e = ss(0.42, 0.8, u), env = Math.sin(e * Math.PI);
                pos.x = m.sx + (m.tx - m.sx) * e * 0.7; pos.z = m.sz + (m.tz - m.sz) * e * 0.7;
                pos.y = Math.max(m.y0, hang) + (m.ty - Math.max(m.y0, hang)) * e;
                Goof.tilt(r, 1.0 * env, 0, true);
                r.armL.shoulder.rotation.set(-2.9 + e * 2.2, 0, 0.3); r.armR.shoulder.rotation.set(-2.9 + e * 2.2, 0, -0.3);
                r.legL.hip.rotation.x = -0.9 * env + Math.sin(m.t * 24) * 0.4; r.legR.hip.rotation.x = -0.4 * env - Math.sin(m.t * 24) * 0.4;
                r.head.rotation.x = -0.35 * env;
            } else {                                                                  // stand up, arms out for balance
                const e = ss(0.8, 1, u);
                pos.x = m.sx + (m.tx - m.sx) * (0.7 + 0.3 * e); pos.z = m.sz + (m.tz - m.sz) * (0.7 + 0.3 * e); pos.y = m.ty;
                Goof.tilt(r, 0.5 * (1 - e), 0, true);
                r.armL.shoulder.rotation.set(-0.2, 0, 0.9 * (1 - e)); r.armR.shoulder.rotation.set(-0.2, 0, -0.9 * (1 - e));
            }
        }
        if (u >= 1) {
            pos.x = m.tx; pos.z = m.tz; pos.y = m.ty;
            r.pelvis.rotation.x = 0; r.head.rotation.set(0, 0, 0); r.spine.rotation.set(0, 0, 0);
            r.legL.hip.rotation.set(0, 0, 0); r.legR.hip.rotation.set(0, 0, 0);
            r.velY = 0; r.canJump = true; this.active = null;
            if (m.kind === 'climb') { for (let i = 0; i < 6; i++) Smoke.emit(V(pos.x, pos.y + 0.2, pos.z), V(rr(-1.5, 1.5), rr(0.5, 1.2), rr(-1.5, 1.5)), 0xb8ad94); SFX.thud(0.4); }
        }
    },
};

function settleOnTerrain(v, blend) {
    const B = v.cfg, g = v.group, c = Math.cos(g.rotation.y), s = Math.sin(g.rotation.y);
    const h = (lx, lz) => getTerrainHeight(g.position.x + lx * c + lz * s, g.position.z - lx * s + lz * c);
    const hF = (h(-B.wheelX, B.wheelF) + h(B.wheelX, B.wheelF)) / 2, hB = (h(-B.wheelX, B.wheelR) + h(B.wheelX, B.wheelR)) / 2;
    const hR = (h(B.wheelX, B.wheelF) + h(B.wheelX, B.wheelR)) / 2, hL = (h(-B.wheelX, B.wheelF) + h(-B.wheelX, B.wheelR)) / 2;
    v.pitch += (Math.atan2(hB - hF, B.wheelF - B.wheelR) - v.pitch) * blend;
    v.roll += (Math.atan2(hR - hL, B.wheelX * 2) - v.roll) * blend;
    g.rotation.x = v.pitch; g.rotation.z = v.roll;
    g.position.y = (hF + hB) / 2;
}

// Drive whichever vehicle the player is in (UTV or truck share this)
function updateVehicle(v, delta) {
    const B = v.cfg, g = v.group;
    let throttle = clamp((keys.w ? 1 : 0) - (keys.s ? 1 : 0) + joy.y, -1, 1);
    const steer = clamp((keys.a ? 1 : 0) - (keys.d ? 1 : 0) - joy.x, -1, 1);
    const boosting = keys.shift || Touch.sprint;
    const maxSpeed = boosting ? B.boostSpeed : B.maxSpeed;
    if (!Engines.running(v)) throttle = 0;                     // still cranking / shut off
    else if (!burnFuel(v, delta, boosting)) throttle = 0;      // dry tank: no power, just coast to a stop
    v.throttle = Math.abs(throttle);

    if (Math.abs(throttle) > 0.05) v.speed = clamp(v.speed + throttle * B.accel * delta, -B.reverseMax, maxSpeed);
    else v.speed *= Math.pow(B.coast, delta);

    if (Math.abs(v.speed) > 0.5) {
        const turn = Math.sign(v.speed) * Math.min(1, Math.abs(v.speed) / 12);
        g.rotation.y += steer * B.turnRate * turn * delta;
    }
    g.position.x += Math.sin(g.rotation.y) * v.speed * delta;
    g.position.z += Math.cos(g.rotation.y) * v.speed * delta;

    // collisions with trees / rocks / bushes / base station / the other vehicle
    const impact = resolveVehicleVsStatics(v);
    if (impact > 0 && Math.abs(v.speed) > 1.5) {
        if (typeof v.lastHit === 'string' && v.lastHit.startsWith('vehicle:')) {        // bumper cars
            const other = VEHICLES.find(o => 'vehicle:' + o.name === v.lastHit);
            Bump.vehicles(v, other, Math.abs(v.speed));
        } else {
            if (Math.abs(v.speed) > 12) showToast(crashLine(v));
            v.speed = -v.speed * B.bounce;
        }
    }
    Wild.bumpAnimals(v, delta);

    settleOnTerrain(v, Math.min(1, delta * 8));
    v.wheels.forEach(w => { w.rotation.x += v.speed * delta * B.wheelSpin; });
    v.steeringWheel.rotation.z += (-steer * 0.9 - v.steeringWheel.rotation.z) * Math.min(1, delta * 10);
    v.frontPivots.forEach(p => { p.rotation.y = -v.steeringWheel.rotation.z * 0.45; });
    poseSeated(rig, v.steeringWheel.rotation.z);
    Bump.whipPose(rig, delta);
}

// with the shotgun out (or squared up to fight) the slung rod swaps to the other shoulder, so it never sits in the shoulder-cam sights
function updateRodSling() {
    const m = (S.gunOut || Aim.stance() || Aim.working()) ? 1 : 0, rb = rig.rodBack;
    rb.mir = (rb.mir || 0) + (m - (rb.mir || 0)) * 0.2;
    rb.position.x = 0.9 - 1.8 * rb.mir; rb.rotation.z = 0.42 - 1.0 * rb.mir;
}
function updatePlayer(delta, firstPerson) {
    const P = CONFIG.player, pos = playerGroup.position;
    const inZ = clamp((keys.w ? 1 : 0) - (keys.s ? 1 : 0) + joy.y, -1, 1);
    const inX = clamp((keys.d ? 1 : 0) - (keys.a ? 1 : 0) + joy.x, -1, 1);
    const mag = Math.min(1, Math.hypot(inX, inZ));                // joystick = analog speed
    const moving = !menusOpen() && mag > 0.08;
    if (!Ctl.sprintHold && keys.shift && !Slide.active && (!moving || S.exhausted)) keys.shift = false;     // sprint toggle drops when you stop or run dry
    const sprint = (keys.shift || Touch.sprint) && moving && !S.exhausted;     // out of stamina = walk only
    Vitals.stamina(delta, sprint);
    Slide.update(delta); Roll.update(delta);

    if (S.seat) {                                    // sitting: any move input stands you up
        if (moving) standUp(); else { poseChair(rig); return; }
    }
    if (Mantle.active) {                             // mid-vault / climb: the move drives everything
        Slide.active = false;
        if (S.dead || S.health <= 0) Mantle.cancel(); else { Mantle.step(delta); return; }
    }
    // this frame's horizontal travel (walking + any knockback), applied in small swept steps below
    let mvx = 0, mvz = 0;
    if (S.knock) {                                   // shoved by a boar / snake
        mvx += S.knock.x * delta; mvz += S.knock.z * delta;
        S.knock.x *= Math.pow(0.02, delta); S.knock.z *= Math.pow(0.02, delta);
        if ((S.knock.t -= delta) <= 0) S.knock = null;
    }
    if (Slide.active) { const sv = Slide.advance(delta); mvx += sv.x * delta; mvz += sv.z * delta; }
    if (Roll.active) { const rv = Roll.advance(delta); mvx += rv.x * delta; mvz += rv.z * delta; }
    if (moving && !Slide.active && !Roll.active) {
        const speed = (sprint && !Aim.on() ? P.sprint : P.walk) * mag * (Aim.on() ? 0.62 : 1);
        _move.set(-Math.sin(cam.yaw) * inZ + Math.cos(cam.yaw) * inX, 0, -Math.cos(cam.yaw) * inZ - Math.sin(cam.yaw) * inX).normalize();
        mvx += _move.x * speed * delta;
        mvz += _move.z * speed * delta;
        if (!firstPerson) {
            let diff = Math.atan2(_move.x, _move.z) - playerGroup.rotation.y;
            diff = Math.atan2(Math.sin(diff), Math.cos(diff));
            playerGroup.rotation.y += diff * Math.min(1, 13 * delta);
        }
        rig.walkPhase += delta * (sprint ? 13.5 : 8.5) * Math.max(0.45, mag);
        // comic "HUS HUS HUS" — one puff per stride while sprinting on the ground
        const cyc = Math.floor(rig.walkPhase / (Math.PI * 2));
        if (sprint && rig.canJump && cyc !== Slide.hcyc) {
            const yw = playerGroup.rotation.y, W = playerGroup.position;
            Pow.show(V(W.x - Math.sin(yw) * 1.4, W.y + 4.6, W.z - Math.cos(yw) * 1.4), 'HUS!', false, 'hus'); SFX.hus();
        }
        Slide.hcyc = cyc;
    }
    if (firstPerson) playerGroup.rotation.y = cam.yaw + Math.PI;
    else if ((S.gunOut || Aim.stance()) && !Roll.active && !Slide.active) {                             // shotgun out / mid-fight: square up to where the crosshair points (strafe)
        let diff = cam.yaw + Math.PI - playerGroup.rotation.y;
        diff = Math.atan2(Math.sin(diff), Math.cos(diff));
        playerGroup.rotation.y += diff * Math.min(1, 16 * delta);
    }
    Combat.moving = moving; Combat.sprint = sprint;

    // collisions: trees / rocks / walls, then the parked vehicles. Swept in <= 0.25-unit steps so a
    // long frame (slow phone, hitch) can't carry you through a thin conex wall in one jump.
    const steps = Math.max(1, Math.ceil(Math.hypot(mvx, mvz) / 0.25)), sx0 = pos.x, sz0 = pos.z;
    for (let i = 0; i < steps; i++) {
        pos.x += mvx / steps; pos.z += mvz / steps;
        resolvePlayerVsStatics(pos, P.radius, pos.y);
        VEHICLES.forEach(v => { const M = v.cfg.mantle, top = M ? v.group.position.y + Math.max(...M.map(q => q.y)) : 0; if (M && pos.y >= top - 0.5) return; pushCircleOutOfBox(pos, P.radius, vehicleBox(v)); });   // (standing on a roof: not inside it)
    }

    // gravity + ground (terrain or the top of a rock/stump/log)
    rig.velY -= P.gravity * delta;
    const prevY = pos.y;
    pos.y += rig.velY * delta;
    // judge landings from where the feet were at the start of the frame, so a long frame can't drop you through a stair / deck
    const ground = supportHeight(pos.x, pos.z, P.radius, Math.max(pos.y, prevY));
    if (pos.y <= ground) { pos.y = ground; rig.velY = 0; rig.canJump = true; }

    // a slide that plows into something stops there
    if (Slide.active && (!rig.canJump || S.dead)) Slide.end(false);
    if (Roll.active && (S.dead || Roll.t > 0.12 && Math.hypot(mvx, mvz) > 0.3 && Math.hypot(pos.x - sx0, pos.z - sz0) < Math.hypot(mvx, mvz) * 0.3)) Roll.end(Roll.t > 0.12);
    if (Slide.active && Slide.t > 0.12) { const want = Math.hypot(mvx, mvz), got = Math.hypot(pos.x - sx0, pos.z - sz0); if (want > 0.3 && got < want * 0.3) Slide.end(true); }
    const emptyHands = !S.lathOut && !(S.hasRtkRod && !S.rodSlung) && !S.gunOut;
    poseWalk(rig, delta, moving || Slide.active, sprint || Slide.active, S.hasRtkRod && !S.rodSlung, emptyHands);
    Slide.poseRig(rig, delta, Slide.active);
    Roll.poseRig(rig);
    Hands.apply(rig, delta);
    Combat.pose(rig, delta, moving);
}

function updateCamera(firstPerson) {
    if (S.title) { Title.camera(); return; }
    if (Jon.inside) {                                                   // in the booth: sitting on the seat, looking around, first person
        const u = Jon.inside, p = localToWorldXZ(u.x, u.z, u.yaw, 0, -0.85), eye = V(p.x, u.y + 4.55, p.z);
        const face = u.yaw + Math.PI, d = Math.atan2(Math.sin(cam.yaw - face), Math.cos(cam.yaw - face));
        cam.yaw = face + clamp(d, -2.3, 2.3); cam.pitch = clamp(cam.pitch, -0.9, 1.15);
        if (Math.abs(camera.fov - 74) > 0.05) { camera.fov = 74; camera.updateProjectionMatrix(); }
        camera.position.copy(eye);
        camera.lookAt(eye.x - Math.sin(cam.yaw) * Math.cos(cam.pitch) * 10, eye.y - Math.sin(cam.pitch) * 10, eye.z - Math.cos(cam.yaw) * Math.cos(cam.pitch) * 10);
        sky.position.copy(camera.position); GrassField.update(camera.position);
        sunLight.target.position.copy(eye); sunLight.position.copy(eye).add(SUN_OFFSET);
        return;
    }
    let focus;
    if (S.vehicle) {
        const v = S.vehicle, st = S.pass && v.cfg.seat2 ? v.cfg.seat2 : v.cfg.seat, gp = v.group.position;
        focus = firstPerson
            ? v.group.localToWorld(V(st.x, st.y + 2.6 + 2.95, st.z + 0.35))
            : V(gp.x, gp.y + v.cfg.camHeight, gp.z);
    } else {
        focus = V(playerGroup.position.x, playerGroup.position.y + 5.55, playerGroup.position.z);
        // shotgun out / mid-fight: GTA-style over-the-shoulder camera; the ray through the crosshair runs parallel to your view, so what you aim at is what you hit
        const want = (S.gunOut || Aim.stance() || Aim.working()) && !firstPerson ? 1 : 0;
        if (!S.gunOut && S.ads) Aim.set(false);
        cam.aim = (cam.aim || 0) + (want - (cam.aim || 0)) * 0.16;
        Aim.ads += ((Aim.on() ? 1 : 0) - Aim.ads) * 0.2;
        const k = cam.aim, ad = Aim.ads, side = lerp(2.7, 1.9, ad);
        if (k > 0.001) { focus.x += Math.cos(cam.yaw) * side * k; focus.z -= Math.sin(cam.yaw) * side * k; focus.y += lerp(1.0, 0.55, ad) * k; }
    }
    {   // sights: zoom the lens
        const fovWant = CONFIG.camera.fov - 24 * (Aim.ads || 0);
        if (Math.abs(camera.fov - fovWant) > 0.05) { camera.fov = fovWant; camera.updateProjectionMatrix(); }
        document.body.classList.toggle('ads-on', Aim.on());
    }
    if (firstPerson) {
        camera.position.copy(focus);
        camera.lookAt(focus.x - Math.sin(cam.yaw) * Math.cos(cam.pitch) * 10, focus.y - Math.sin(cam.pitch) * 10, focus.z - Math.cos(cam.yaw) * Math.cos(cam.pitch) * 10);
    } else {
        const dir = V(Math.sin(cam.yaw) * Math.cos(cam.pitch), Math.sin(cam.pitch), Math.cos(cam.yaw) * Math.cos(cam.pitch));
        let dist = S.vehicle ? cam.dist : siteCameraDist(focus, dir, cam.dist);
        if (!S.vehicle && cam.aim > 0.001) dist = Math.min(dist, lerp(dist, lerp(13.5, 8.0, Aim.ads || 0), cam.aim));
        // looking up: pull the camera in instead of burying it, so you can actually tip your view at the sky / the balcony
        if (dir.y < -0.02) { const floor = (S.vehicle ? getTerrainHeight(focus.x, focus.z) : playerGroup.position.y) + 1.0; dist = Math.min(dist, Math.max(1.6, (focus.y - floor) / -dir.y)); }
        camera.position.copy(focus).addScaledVector(dir, dist);
        const gy = getTerrainHeight(camera.position.x, camera.position.z);
        if (camera.position.y < gy + 1.2) camera.position.y = gy + 1.2;
        camera.lookAt(focus);
    }
    sky.position.copy(camera.position);
    GrassField.update(camera.position);
    // shadows follow the action
    sunLight.target.position.set(focus.x, focus.y, focus.z);
    sunLight.position.copy(focus).add(SUN_OFFSET);
}

function updatePrompt() {
    const p = $('interaction-prompt');
    const show = (key, text) => { p.style.display = 'flex'; p.innerHTML = `<span class="key-cap">${key}</span> ${text}`; };
    if (menusOpen()) { p.style.display = 'none'; return; }
    if (S.driving) {
        if (!S.pass && S.vehicle.forklift && Delivery.live()) {
            const fa = Delivery.forkAction(S.vehicle);
            if (fa) show('F', fa.label);
            else show('F', 'Exit ' + S.vehicle.cfg.label + ' <span style="opacity:.75">· drive the forks up to a panel box to lift it</span>');
            return;
        }
        if (S.pass) show('F', 'Hop out of ' + S.vehicle.cfg.label);
        else if (S.vehicle.fuel <= 0) show('F', 'OUT OF FUEL — Exit ' + S.vehicle.cfg.label);
        else show('F', 'Exit ' + S.vehicle.cfg.label);
        return;
    }
    if (S.warn && performance.now() < S.warn.until) { show('!', S.warn.text); return; }
    const lines = [];
    if (!S.seat && (Boars.nearest(playerGroup.position, 15) || Coyotes.nearest(playerGroup.position, 15) || Snakes.nearest(playerGroup.position, 10) || Bears.nearest(playerGroup.position, 16) || Net.nearestFoe(playerGroup.position, 8))) {
        if (S.gunOut) lines.push(['CLICK', 'Light it up!']);
        else if (Combat.handsEmpty()) lines.push(['V', 'Throw hands!']);
        else if (S.hasRtkRod) lines.push(['V', 'Swing the rod!']);
    }
    const ns = !S.seat && nearestStake();
    if (ns) lines.push(['R', `Pull up stake "${ns.label}"`]);
    const zone = S.seat ? null : nearestZone(), use = useTarget();
    if (zone === 'rod') lines.push(['G', rodZoneAction(nearestZone.b).text]);
    else if (zone === 'bed') lines.push(['G', 'Grab Wood Lath & Configure Color Line / Marker']);
    else if (zone === 'can') lines.push(['G', S.hasGasCan ? 'Put the gas can back' : 'Grab the gas can']);
    if (use) lines.push(['F', use.label]);
    if (!lines.length) { p.style.display = 'none'; return; }
    p.style.display = 'flex';
    p.innerHTML = lines.map(([k, t]) => `<span class="key-cap">${k}</span> ${t}`).join('<span class="prompt-sep"></span>');
}

function updateCoordsHud() {
    if (!S.hasRtkRod || !S.baseOn) return;
    const t = getRoverTipWorldPos();
    setText('sc-n', (5000 - t.z).toFixed(2));
    setText('sc-e', (5000 + t.x).toFixed(2));
    setText('sc-z', (100 + t.y).toFixed(2));
}

// =====================================================================
// [LOOP]
// =====================================================================
let prevTime = performance.now();
function animate() {
    requestAnimationFrame(animate);
    const now = performance.now(), delta = Math.min((now - prevTime) / 1000, 0.1);
    prevTime = now;
    WIND.value = now / 1000;
    BUGGIES.forEach((b, i) => { b.beaconLight.intensity = Math.sin(now * 0.015 + i * 1.6) > 0 ? 3.5 : 0.3; });

    Look.tick(delta);
    cam.dist += (cam.target - cam.dist) * Math.min(1, delta * 14);
    const firstPerson = cam.dist < 1.0;
    BUGGIES.forEach(b => {
        // doors stay shut; each one swings open for a moment when someone gets in or out on that side
        const dOcc = !!((S.vehicle === b && !S.pass) || b.remoteBy), pOcc = !!((S.vehicle === b && S.pass) || b.pass);
        if (b.dOcc !== undefined && dOcc !== b.dOcc) b.dSwing = now + 900;
        if (b.pOcc !== undefined && pOcc !== b.pOcc) b.pSwing = now + 900;
        b.dOcc = dOcc; b.pOcc = pOcc;
        const doorTarget = now < (b.dSwing || 0) ? CONFIG.buggy.doorOpenAngle : 0;
        b.driverDoor.rotation.y += (doorTarget - b.driverDoor.rotation.y) * Math.min(1, delta * 6);
        const pT = now < (b.pSwing || 0) ? -CONFIG.buggy.doorOpenAngle : 0;
        b.passengerDoor.rotation.y += (pT - b.passengerDoor.rotation.y) * Math.min(1, delta * 6);
    });

    TruckDoors.update(delta, now);
    updateRodSling();
    if (S.pass) {                                    // riding: the driver's phone moves the vehicle; the ride ends when they park
        const v = S.vehicle;
        if (!v || !v.remoteBy || S.dead || S.health <= 0) handleVehicleToggle(); else poseRider(rig);
    } else if (S.vehicle) updateVehicle(S.vehicle, delta);
    else if (Jon.inside) Jon.hold(delta);
    else updatePlayer(delta, firstPerson);
    Net.update(delta, now);
    CrewUTV.tick(now);
    Bump.update(delta);
    Engines.update(delta);
    Smoke.update(delta);
    updateAnims(delta);
    Vitals.pose(delta, now);
    Radar.update(now);
    updateSite(delta, now);
    Justin.update(delta);
    Greg.update(delta, now);
    Inspector.update(delta, now);
    Jon.update(delta, now);
    Becky.update(delta, now); Delivery.update(delta, now); Storage.update();
    Spray.update(delta, now); Trees.update(delta, now); PowerHum.update(); TaskTip.update(now); Island.tick(now);
    JobBox.update(delta);
    PPE.update();
    Inv.update(delta);
    if (S.caught) {                                  // frozen with your hands up while he blows the whistle
        keys.w = keys.a = keys.s = keys.d = false; joy.x = joy.y = 0;
        if (!S.vehicle) { rig.armL.shoulder.rotation.set(-2.9, 0, 0.35); rig.armR.shoulder.rotation.set(-2.9, 0, -0.35); rig.armL.elbow.rotation.x = -0.4; rig.armR.elbow.rotation.x = -0.4; }
    }
    Deer.update(delta);
    Gun.update(delta);
    Boars.update(delta, now);
    Bears.update(delta, now);
    Coyotes.update(delta, now);
    Wild.tumble(delta);
    Snakes.update(delta, now);
    MiniGame.update(delta);
    ControlPoints.update(now);
    Pockets.update(now);
    Hands.tick(delta);
    Hotbar.update(now);
    Inv.tick();
    TaskManager.update(now);
    TaskManager.topoTick();
    Vitals.update(delta, now);
    Clouds.update(delta);
    updateFuelHud(false);
    Save.tick(now);
    playerGroup.visible = !firstPerson && !Jon.inside;

    updateCamera(firstPerson);
    Shake.apply(delta);
    Crosshair.update(delta, Combat.moving, Combat.sprint);
    updatePrompt();
    TouchUI.update();
    updateCoordsHud();
    if (now - (drawRadar.at || 0) > 33) { drawRadar.at = now; drawRadar(); }          // the minimap redraws ~30×/s (smooth enough, half the canvas work at 60 FPS)
    BigMap.draw();
    Net.updateTags();
    Cull.update(now);
    Forest.update(now);
    if (!S.invOpen || now - (animate.lastFull || 0) > 100) { animate.lastFull = now; renderer.render(scene, camera); }     // behind the inventory: 10 FPS is enough
    updateDebugStats(now);
}

// =====================================================================================================
// [TITLE]  Main menu: PLAY → site select → SOLO / ONLINE (host a room code or join one), OPTIONS
//          (Audio / Graphics / Controls), MULTIPLAYER, EXIT. The live 3D site drifts behind it.
//          Room codes: everyone who opens the game shares one claude.ai room; players only see crewmates
//          whose presence carries the same `rc` code (Net.reconcile filters on it).
// =====================================================================================================
const Title = {
    active: false, el: null, cur: null, stack: [], map: 'memphis', mapChosen: false, afterMap: 'mode',
    code: null, t0: 0, optTab: 'audio', moved: [], joinTimer: 0, hostTimer: 0,
    MAPS: [
        { id: 'memphis', name: 'MEMPHIS, TN', sub: 'Mid-South solar site', ready: true, art: 'memphis' },
        { id: 'amarillo', name: 'AMARILLO, TX', sub: 'High Plains · coming soon', ready: false, art: 'plains' },
        { id: 'more', name: 'MORE SITES', sub: 'From the Site Builder', ready: false, art: 'more' },
    ],
    init() {
        if (navigator.webdriver && !window.__TITLE) { Net.rc = 'TEST'; Net.init(); return; }      // automated tests: straight in
        const rj = Rejoin.take();
        this.build();
        this.active = true; S.title = true; this.t0 = performance.now(); this.camWas = { yaw: cam.yaw, pitch: cam.pitch };
        this.stage();
        document.body.classList.add('title-on');
        this.go('main', 'first');
        ['keydown', 'keyup'].forEach(ev => document.addEventListener(ev, e => this.key(e), true));
        if (!rj && typeof JUMP_GO !== 'undefined' && JUMP_GO && JUMP_GO.solo) setTimeout(() => { if (this.active) { this.mapChosen = true; this.start('solo'); } }, 400);    // debug jump, solo: skip the menus
        if (rj) (async () => {                                                        // straight back into the room after a re-sync / host wipe
            const ok = await this.netUp();
            if (!ok || !this.active) return;
            Net.rc = rj.rc; Net.host = !!rj.host; Net.force = true; this.mapChosen = true; this.code = rj.rc;
            this.start('online');
            setTimeout(() => showToast(rj.host ? `🔄 Fresh job — you're back in room ${rj.rc}.` : `🔄 Re-synced with the crew in room ${rj.rc}.`), 900);
        })();
    },
    // ---------------- markup ----------------
    build() {
        const B = (txt, act, i, extra = '') => `<button class="tm-btn ${extra}" data-act="${act}" style="--i:${i}">${txt}</button>`;
        const cards = this.MAPS.map((m, k) => `<button class="tm-card${m.ready ? '' : ' locked'}" data-map="${m.id}" style="--i:${k + 1}" ${m.ready ? '' : 'aria-disabled="true"'}>
            <span class="tm-art tm-art-${m.art}">${m.ready ? '' : '<b>🔒</b>'}</span><span class="tm-cname">${m.name}</span><span class="tm-csub">${m.sub}</span></button>`).join('');
        const el = document.createElement('div'); el.id = 'tm';
        el.innerHTML = `<div class="tm-bg"></div>
        <section class="tm-screen" data-s="main">
            <div class="tm-logo" style="--i:0"><span class="tm-l1">SOLAR SITE</span><span class="tm-l2">SURVEY SIM</span></div>
            ${B('PLAY', 'play', 1)}${B('OPTIONS', 'options', 2)}${B('EXIT', 'exit', 3)}
        </section>
        <section class="tm-screen" data-s="maps">
            <div class="tm-head" style="--i:0">SELECT SITE</div>
            <div class="tm-cards">${cards}</div>
            ${B('BACK', 'back', 5, 'small')}
        </section>
        <section class="tm-screen" data-s="mode">
            <div class="tm-head" style="--i:0">MEMPHIS, TN</div>
            ${B('SOLO', 'solo', 1)}${B('ONLINE', 'online', 2)}${B('BACK', 'back', 3, 'small')}
        </section>
        <section class="tm-screen" data-s="online">
            <div class="tm-head" style="--i:0">ONLINE CREW</div>
            ${B('HOST GAME', 'host', 1)}${B('JOIN GAME', 'join', 2)}${B('BACK', 'back', 3, 'small')}
        </section>
        <section class="tm-screen" data-s="host">
            <div class="tm-head" style="--i:0">ROOM CODE</div>
            <div class="tm-code" id="tm-code" style="--i:1">····</div>
            <div class="tm-status" id="tm-host-status" style="--i:2">Connecting…</div>
            <div class="tm-crew" id="tm-host-crew" style="--i:3"></div>
            ${B('START', 'hoststart', 4)}${B('COPY CODE', 'copy', 5, 'small')}${B('BACK', 'back', 6, 'small')}
        </section>
        <section class="tm-screen" data-s="join">
            <div class="tm-head" style="--i:0">JOIN A CREW</div>
            <input class="tm-input" id="tm-join-code" style="--i:1" maxlength="4" placeholder="CODE" autocomplete="off" autocapitalize="characters" spellcheck="false" enterkeyhint="go">
            <div class="tm-status" id="tm-join-status" style="--i:2">Ask the host for their 4-letter room code.</div>
            ${B('JOIN', 'joingo', 3)}${B('JOIN ANYWAY', 'joinforce', 4, 'small hide')}${B('BACK', 'back', 5, 'small')}
        </section>
        <section class="tm-screen" data-s="look">
            <div class="tm-head" style="--i:0">YOUR SURVEYOR</div>
            <div class="tm-tabs" style="--i:1">${B('MALE', 'g:m', 0, 'tab')}${B('FEMALE', 'g:f', 0, 'tab')}</div>
            <div class="tm-lbl" style="--i:2">SKIN TONE</div>
            <div class="tm-sw" style="--i:2">${LOOK.SKINS.map((c, k) => `<button class="tm-swatch" data-act="s:${k}" style="--c:#${c.toString(16).padStart(6, '0')}" aria-label="Skin tone ${k + 1}"></button>`).join('')}</div>
            <div class="tm-lbl" style="--i:3">JACKET</div>
            <div class="tm-sw" style="--i:3">${LOOK.JACKETS.map((c, k) => `<button class="tm-swatch" data-act="j:${k}" style="--c:#${c.toString(16).padStart(6, '0')}" aria-label="Jacket colour ${k + 1}"></button>`).join('')}</div>
            ${B("LET'S GO", 'lookgo', 4)}${B('BACK', 'back', 5, 'small')}
        </section>
        <section class="tm-screen" data-s="options">
            <div class="tm-head" style="--i:0">OPTIONS</div>
            <div class="tm-tabs" style="--i:1">${B('AUDIO', 'tab:audio', 0, 'tab')}${B('GRAPHICS', 'tab:graphics', 0, 'tab')}${B('CONTROLS', 'tab:controls', 0, 'tab')}</div>
            <div class="tm-panel" id="tm-opt-body" style="--i:2"></div>
            ${B('BACK', 'back', 3, 'small')}
        </section>
        <section class="tm-screen" data-s="exit">
            <div class="tm-head" style="--i:0">SEE YOU ON SITE</div>
            <div class="tm-status" style="--i:1">Thanks for surveying. You can close this tab.</div>
            ${B('BACK TO MENU', 'back', 2)}
        </section>
        <div class="tm-foot"><span class="tm-keys">↑ ↓ select · Enter confirm · Esc back</span><span>v1.56.1</span></div>`;
        document.body.appendChild(el); this.el = el;
        el.addEventListener('click', e => {
            const card = e.target.closest('.tm-card');
            if (card) { this.pickMap(card); return; }
            const b = e.target.closest('[data-act]'); if (!b || b.disabled) return;
            if (b.classList.contains('tm-btn')) this.press(b); else this.sfx(true);
            this.act(b.dataset.act);
        });
        el.addEventListener('pointerover', e => { const b = e.target.closest('.tm-btn, .tm-card, .tm-swatch'); if (b && !b.disabled) this.select(b, true); });
        ['touchstart', 'touchmove', 'touchend', 'pointerdown', 'mousedown', 'wheel'].forEach(ev => el.addEventListener(ev, e => e.stopPropagation()));
        const inp = el.querySelector('#tm-join-code');
        inp.addEventListener('input', () => { const v = inp.value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 4); if (v !== inp.value) inp.value = v; });
    },
    // ---------------- screens ----------------
    screen(name) { return this.el.querySelector(`.tm-screen[data-s="${name}"]`); },
    go(name, dir = 'fwd') {
        const next = this.screen(name), prev = this.cur ? this.screen(this.cur) : null;
        if (dir === 'fwd' && this.cur) this.stack.push(this.cur);
        if (this.cur === 'options') this.returnPages();
        this.leave(this.cur);
        const back = dir === 'back';
        if (prev) { prev.classList.remove('back'); prev.classList.add('out'); if (back) prev.classList.add('back'); setTimeout(() => { prev.classList.remove('on', 'out', 'back'); }, 230); }
        setTimeout(() => {
            next.classList.remove('out', 'back'); if (back) next.classList.add('back');
            next.classList.add('on'); this.cur = name; this.enter(name);
            this.el.querySelectorAll('.sel').forEach(x => x.classList.remove('sel'));
            const first = next.querySelector('.tm-card:not(.locked).picked') || next.querySelector('.tm-btn:not(.small):not(.tab):not([disabled]):not(.hide)') || next.querySelector('.tm-card:not(.locked)') || next.querySelector('.tm-btn:not([disabled]):not(.hide)');
            if (first) this.select(first);
        }, prev ? 170 : 0);
    },
    back() {
        if (this.inGame && this.cur === 'look') { this.close(); return; }
        if (!this.stack.length) return;
        if (this.cur === 'host' || this.cur === 'join') { Net.rc = null; Net.host = false; Net.force = true; }
        SFX.blip && this.sfx(false);
        this.go(this.stack.pop(), 'back');
    },
    enter(name) {
        if (name === 'host') this.hostUp();
        if (name === 'join') { const inp = $('tm-join-code'); setText('tm-join-status', 'Ask the host for their 4-letter room code.'); this.el.querySelector('[data-act="joinforce"]').classList.add('hide'); setTimeout(() => { try { inp.focus(); } catch (e) { /* ok */ } }, 260); }
        if (name === 'options') this.tab(this.optTab);
        if (name === 'look') this.lookUI();
        if (name === 'mode') this.screen('mode').querySelector('.tm-head').textContent = (this.MAPS.find(m => m.id === this.map) || this.MAPS[0]).name;
    },
    leave(name) {
        if (name === 'host') { clearInterval(this.hostTimer); }
        if (name === 'join') { clearInterval(this.joinTimer); }
    },
    act(a) {
        switch (a) {
            case 'play': this.afterMap = 'mode'; this.go('maps'); break;
            case 'options': this.go('options'); break;
            case 'multi': this.go('online'); break;
            case 'exit': try { window.close(); } catch (e) { /* not allowed in a page */ } this.go('exit'); break;
            case 'back': this.back(); break;
            case 'solo': this.pending = 'solo'; this.go('look'); break;
            case 'online': this.go('online'); break;
            case 'host': if (!this.mapChosen) { this.afterMap = 'host'; this.go('maps'); } else this.go('host'); break;
            case 'join': this.go('join'); break;
            case 'hoststart': this.pending = 'online'; this.go('look'); break;
            case 'lookgo': if (this.inGame) this.close(); else this.start(this.pending || 'solo'); break;
            case 'copy': this.copy(); break;
            case 'joingo': this.joinTry(false); break;
            case 'joinforce': this.joinTry(true); break;
            default:
                if (a.startsWith('tab:')) this.tab(a.slice(4));
                else if (a.startsWith('g:')) { LOOK.set({ g: a.slice(2) }); this.lookUI(); }
                else if (a.startsWith('s:')) { LOOK.set({ s: +a.slice(2) }); this.lookUI(); }
                else if (a.startsWith('j:')) { LOOK.set({ j: +a.slice(2) }); this.lookUI(); }
        }
    },
    pickMap(card) {
        const m = this.MAPS.find(x => x.id === card.dataset.map);
        if (!m || !m.ready) { card.classList.remove('shake'); void card.offsetWidth; card.classList.add('shake'); this.sfx(false); showToast(`🔒 ${m ? m.name : 'That site'} isn't built yet — coming soon.`); return; }
        this.press(card); this.map = m.id; this.mapChosen = true;
        this.el.querySelectorAll('.tm-card').forEach(c => c.classList.toggle('picked', c === card));
        this.go(this.afterMap);
    },
    lookUI() {
        const L = LOOK.cur, sc = this.screen('look'); if (!sc) return;
        sc.querySelectorAll('[data-act^="g:"]').forEach(b => b.classList.toggle('on', b.dataset.act === 'g:' + L.g));
        sc.querySelectorAll('[data-act^="s:"]').forEach(b => b.classList.toggle('on', +b.dataset.act.slice(2) === L.s));
        sc.querySelectorAll('[data-act^="j:"]').forEach(b => b.classList.toggle('on', +b.dataset.act.slice(2) === L.j));
        sc.querySelector('[data-act="lookgo"]').textContent = this.inGame ? 'DONE' : "LET'S GO";
    },
    // ---------------- back from the game: change appearance in place, or leave the session for the title ----------------
    reopen(screen) {
        if (this.active) return;
        if (S.vehicle) handleVehicleToggle();                         // hop out first: the camera wants you standing
        this.inGame = screen === 'look';
        this.build(); this.active = true; S.title = true; this.t0 = performance.now(); this.stack = []; this.cur = null;
        this.camWas = { yaw: cam.yaw, pitch: cam.pitch }; this.camPos = null;
        if (document.pointerLockElement) document.exitPointerLock();
        if (!this.inGame) { this.mapChosen = false; this.code = null; this.stage(); }
        document.body.classList.add('title-on');
        this.el.classList.toggle('ingame', this.inGame);
        this.go(screen, 'first');
    },
    close() {                                                     // DONE on the in-game appearance screen
        this.active = false; S.title = false; this.inGame = false; document.body.classList.remove('title-on'); this.hideNear(false);
        this.el.classList.add('gone'); const el = this.el; setTimeout(() => el.remove(), 700);
        cam.yaw = this.camWas.yaw; cam.pitch = this.camWas.pitch;
        if (!Touch.active) { try { lockPointer(); } catch (e) { /* needs a click */ } }
    },
    // vehicles parked right by the surveyor get out of the way of the close-up (just hidden; back when you leave the screen)
    hideNear(on) {
        this.hid = this.hid || new Set();
        if (!on) { if (this.hid.size) { this.hid.forEach(v => { v.group.visible = true; }); this.hid.clear(); } return; }
        const P = playerGroup.position;
        VEHICLES.forEach(v => { if (S.vehicle !== v && flatDist(v.group.position, P) < 20) { v.group.visible = false; this.hid.add(v); } });
    },
    leaveSession() {
        if (Net.on) Net.leave();
        this.reopen('main');
    },
    // ---------------- selection / keys / feel ----------------
    select(b, quiet) {
        if (!b || b.classList.contains('sel')) return;
        this.el.querySelectorAll('.sel').forEach(x => x.classList.remove('sel'));
        b.classList.add('sel'); if (!quiet) { try { b.focus({ preventScroll: true }); } catch (e) { /* ok */ } }
    },
    press(b) { b.classList.remove('press'); void b.offsetWidth; b.classList.add('press'); this.sfx(true); },
    sfx(fwd) {
        try {
            const ctx = SFX.ctx(); if (!ctx) return; const t = ctx.currentTime;
            SFX.tone(ctx, t, { type: 'square', from: fwd ? 520 : 360, to: fwd ? 760 : 260, len: 0.07, vol: 0.05 });
            SFX.tone(ctx, t + 0.05, { type: 'triangle', from: fwd ? 1040 : 300, len: 0.06, vol: 0.04 });
        } catch (e) { /* audio not ready */ }
    },
    key(e) {
        if (!this.active) return;
        const inInput = e.target && e.target.tagName === 'INPUT';
        e.stopPropagation();                                                     // the game doesn't see keys while the menu is up
        if (e.type !== 'keydown') return;
        if (e.key === 'Escape') { e.preventDefault(); this.back(); return; }
        if (inInput) { if (e.key === 'Enter') { e.preventDefault(); this.act('joingo'); } return; }
        const scr = this.screen(this.cur); if (!scr) return;
        const list = [...scr.querySelectorAll('.tm-btn:not([disabled]):not(.hide), .tm-card, .tm-swatch')].filter(b => b.offsetParent !== null);
        let i = list.findIndex(b => b.classList.contains('sel'));
        if (['ArrowDown', 'ArrowRight', 'KeyS', 'KeyD', 'Tab'].includes(e.code)) { e.preventDefault(); this.select(list[(i + 1) % list.length]); this.sfxTick(); }
        else if (['ArrowUp', 'ArrowLeft', 'KeyW', 'KeyA'].includes(e.code)) { e.preventDefault(); this.select(list[(i - 1 + list.length) % list.length]); this.sfxTick(); }
        else if (e.key === 'Enter' || e.code === 'Space') { e.preventDefault(); if (i >= 0) list[i].click(); }
    },
    sfxTick() { try { const ctx = SFX.ctx(); if (ctx) SFX.tone(ctx, ctx.currentTime, { type: 'square', from: 420, len: 0.03, vol: 0.03 }); } catch (e) { /* ok */ } },
    // ---------------- options (re-uses the F1 menu's Audio + Graphics pages, so every setting stays wired) ----------------
    tab(name) {
        this.optTab = name; this.returnPages();
        this.el.querySelectorAll('.tm-tabs .tm-btn').forEach(b => b.classList.toggle('on', b.dataset.act === 'tab:' + name));
        const body = $('tm-opt-body'); body.innerHTML = ''; body.classList.remove('pop'); void body.offsetWidth; body.classList.add('pop');
        const page = $(name === 'audio' ? 'dev-page-audio' : name === 'controls' ? 'dev-page-mouse' : 'dev-page-graphics'); if (!page) return;
        this.moved.push({ page, parent: page.parentNode, next: page.nextSibling });
        page.classList.add('active'); body.appendChild(page);
    },
    returnPages() {
        this.moved.forEach(({ page, parent, next }) => { page.classList.remove('active'); parent.insertBefore(page, next); });
        this.moved = [];
    },
    // ---------------- online ----------------
    async netUp() {
        if (!Net.roomTried) { Net.inited = true; Net.roomTried = true; await Net.init(); }
        return Net.on;
    },
    newCode() { const A = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; let c = ''; for (let k = 0; k < 4; k++) c += A[Math.floor(Math.random() * A.length)]; return c; },
    async hostUp() {
        if (!this.code || !Net.host) this.code = this.newCode();
        $('tm-code').innerHTML = this.code.split('').map((ch, k) => `<i style="--k:${k}">${ch}</i>`).join('');
        const start = this.el.querySelector('[data-act="hoststart"]'); start.disabled = true;
        setText('tm-host-status', 'Connecting…');
        const ok = await this.netUp();
        if (this.cur !== 'host') return;
        if (!ok) { setText('tm-host-status', Net.why === 'not on claude.ai' ? 'Online play only works when the game is opened on claude.ai.' : 'Online is unavailable right now (' + (Net.why || 'no connection') + ').'); return; }
        Net.rc = this.code; Net.host = true; Net.force = true;
        start.disabled = false; this.select(start);
        setText('tm-host-status', 'Share this code with your crew, then press START.');
        const crew = () => { const names = ['You (host)'].concat([...Net.remotes.values()].map(R => R.name)); $('tm-host-crew').textContent = `In the room (${names.length}/4): ` + names.join(', '); };
        crew(); clearInterval(this.hostTimer); this.hostTimer = setInterval(crew, 600);
    },
    copy() {
        if (!this.code) return;
        const done = () => setText('tm-host-status', `Copied ${this.code} — send it to your crew.`);
        try { navigator.clipboard.writeText(this.code).then(done, () => setText('tm-host-status', `Code: ${this.code}`)); } catch (e) { setText('tm-host-status', `Code: ${this.code}`); }
    },
    async joinTry(force) {
        const code = ($('tm-join-code').value || '').toUpperCase();
        if (code.length !== 4) { setText('tm-join-status', 'Room codes are 4 letters/numbers.'); return; }
        setText('tm-join-status', `Looking for room ${code}…`);
        const ok = await this.netUp();
        if (this.cur !== 'join') return;
        if (!ok) { setText('tm-join-status', Net.why === 'not on claude.ai' ? 'Online play only works when the game is opened on claude.ai.' : 'Online is unavailable right now.'); return; }
        try {                                                                         // 4 to a crew
            const inRoom = Net.room.peers().filter(p => !p.sameTab && p.presence && p.presence.rc === code).length;
            if (inRoom >= 4) { setText('tm-join-status', `Room ${code} is full (4/4).`); return; }
        } catch (e) { /* can't count: let them try */ }
        Net.rc = code; Net.host = false; Net.force = true; Net.lastPeers = null;
        if (force) { this.pending = 'online'; this.go('look'); return; }
        const t0 = performance.now(); clearInterval(this.joinTimer);
        this.joinTimer = setInterval(() => {
            if (Net.remotes.size) { clearInterval(this.joinTimer); this.pending = 'online'; this.go('look'); return; }
            if (performance.now() - t0 > 6000) {
                clearInterval(this.joinTimer);
                setText('tm-join-status', `Nobody's in room ${code} yet. Check the code, or join anyway and wait for them.`);
                this.el.querySelector('[data-act="joinforce"]').classList.remove('hide');
            }
        }, 300);
    },
    // ---------------- into the game ----------------
    start(mode) {
        if (!this.active) return;
        this.leave(this.cur); this.returnPages();
        this.active = false; S.title = false; this.unstage(); this.hideNear(false);
        this.el.classList.add('gone'); document.body.classList.remove('title-on');
        const el = this.el; setTimeout(() => { el.remove(); }, 700);
        cam.yaw = this.camWas.yaw; cam.pitch = this.camWas.pitch;
        if (mode === 'solo') { if (!Net.inited) { Net.inited = true; Net.init({ offline: true }); } Net.hud(); }
        else {
            Net.hud();
            const code = Net.rc;
            setTimeout(() => showToast(Net.host ? `📡 Hosting room ${code} — your crew joins with that code.` : `📡 Joined room ${code}.`), 600);
        }
        if (!Touch.active) { try { lockPointer(); } catch (e) { /* needs a click */ } }
    },
    // title scene: the surveyor stands by the UTV holding the RTK rod (put back exactly as it was when the game starts)
    cfg: { px: -5.2, pz: 1.2, yaw: Math.PI / 2 + 0.5, a: 1.35, swing: 0.38, r: 21 },
    stage() {
        const P = playerGroup;
        this.saved = { has: S.hasRtkRod, slung: S.rodSlung, from: S.rodFrom, pos: P.position.clone(), rot: P.rotation.y };
        S.hasRtkRod = true; S.rodSlung = false; S.rodFrom = buggy;
        this.place(); updateEquipmentUI();
    },
    place() {
        const P = playerGroup, spot = buggy.group.localToWorld(V(this.cfg.px, 0, this.cfg.pz));
        P.position.set(spot.x, getTerrainHeight(spot.x, spot.z), spot.z); P.rotation.y = buggy.group.rotation.y - Math.PI + this.cfg.yaw;     // relative to wherever the UTV is parked
    },
    unstage() {
        const v = this.saved; if (!v) return;
        S.hasRtkRod = v.has; S.rodSlung = v.slung; S.rodFrom = v.from;
        playerGroup.position.copy(v.pos); playerGroup.rotation.y = v.rot; rig.velY = 0;
        updateEquipmentUI(); this.saved = null;
    },
    // the menu camera: a slow sway in front of the UTV + surveyor (the offices sit behind it at ~120–285°; the truck is behind the camera)
    camera() {
        const t = (performance.now() - this.t0) / 1000, g = this.inGame ? playerGroup.position.clone() : buggy.group.position.clone().lerp(playerGroup.position, 0.35);
        const a = buggy.group.rotation.y - Math.PI + this.cfg.a + Math.sin(t * 0.05) * this.cfg.swing, r = this.cfg.r + Math.sin(t * 0.09) * 2.5;
        const eye = V(g.x + Math.sin(a) * r, 0, g.z + Math.cos(a) * r);
        eye.y = Math.max(getTerrainHeight(eye.x, eye.z) + 2.2, g.y + 3.6 + Math.sin(t * 0.13) * 0.7);
        const dx = g.x - eye.x, dz = g.z - eye.z, L = Math.hypot(dx, dz) || 1;
        const look = V(g.x - (-dz / L) * 7.5, g.y + 3.0, g.z - (dx / L) * 7.5);
        this.hideNear(this.cur === 'look');
        if (this.cur === 'look') {                                    // close-up on the surveyor while you pick
            const P = playerGroup.position, ay = playerGroup.rotation.y - (this.inGame ? 0.35 : 0.6) + Math.sin(t * 0.25) * 0.15;     // 3/4 front, turned away from the office deck
            eye.set(P.x + Math.sin(ay) * 10.5, P.y + 5.0, P.z + Math.cos(ay) * 10.5);
            const fx = P.x - eye.x, fz = P.z - eye.z, fl = Math.hypot(fx, fz) || 1;
            look.set(P.x + (fz / fl) * 2.9, P.y + 3.7, P.z - (fx / fl) * 2.9);            // aim left of them so they stand right of the buttons
        }
        if (Math.abs(camera.fov - 55) > 0.05) { camera.fov = 55; camera.updateProjectionMatrix(); }
        if (!this.camPos) { this.camPos = eye.clone(); this.camLook = look.clone(); }
        const nowT = performance.now(), dt = Math.min(0.1, (nowT - (this.camT || nowT)) / 1000); this.camT = nowT;
        const kk = 1 - Math.exp(-dt * 3.2); this.camPos.lerp(eye, kk); this.camLook.lerp(look, kk);
        camera.position.copy(this.camPos); camera.lookAt(this.camLook);
        sky.position.copy(camera.position); GrassField.update(camera.position);
        sunLight.target.position.copy(g); sunLight.position.copy(g).add(SUN_OFFSET);
        if (S.health < 100) S.health = 100;
    },
};

// =====================================================================================================
// [STORAGE]  A 20' storage conex behind the break room, end doors swung wide open facing east, steel racks inside
//            (tools on one side). Becky, the warehouse manager, stands out front. After her delivery job the empty
//            racks fill with torque tubes and panels.
// =====================================================================================================
const STORE = { x: 22, z: -64, L: 20, W: 8, H: 8.4, t: 0.25 };
const Storage = {
    group: null, fill: null,
    // interior (world, axis-aligned: the box faces +x)
    inside(x, z, m = 0) { return x > STORE.x - STORE.L / 2 + 0.3 - m && x < STORE.x + STORE.L / 2 + m && Math.abs(z - STORE.z) < STORE.W / 2 - 0.3 + m; },
    init() {
        const g = new THREE.Group(), y0 = getTerrainHeight(STORE.x, STORE.z); g.position.set(STORE.x, y0, STORE.z); scene.add(g); this.group = g;
        const { L, W, H, t } = STORE;
        const shell = new THREE.MeshStandardMaterial({ color: 0x6b7f8f, roughness: 0.6, metalness: 0.25 });
        const inner = new THREE.MeshStandardMaterial({ color: 0xd7dcdf, roughness: 0.7 });
        const rib = new THREE.MeshStandardMaterial({ color: 0x5c6f7e, roughness: 0.6, metalness: 0.25 });
        const ply = new THREE.MeshStandardMaterial({ color: 0x8a6a45, roughness: 0.9 });
        const box = (w, h, d, m, x, y, z, par = g, rot) => { const o = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); o.position.set(x, y, z); if (rot) o.rotation.set(...rot); o.castShadow = true; o.receiveShadow = true; par.add(o); return o; };
        // walls (back at -x, two long sides), roof, floor
        box(t, H, W, shell, -L / 2, H / 2, 0); box(L, H, t, shell, 0, H / 2, -W / 2); box(L, H, t, shell, 0, H / 2, W / 2);
        box(L + 0.2, 0.25, W + 0.2, shell, 0, H, 0); box(L, 0.2, W, ply, 0, 0.1, 0);
        box(t * 0.6, H - 0.4, W - 0.6, inner, -L / 2 + 0.2, H / 2, 0); box(L - 0.4, H - 0.4, t * 0.6, inner, 0, H / 2, -W / 2 + 0.2); box(L - 0.4, H - 0.4, t * 0.6, inner, 0, H / 2, W / 2 - 0.2);
        for (let x = -L / 2 + 0.8; x < L / 2; x += 1.1) [-1, 1].forEach(s => box(0.45, H - 0.6, 0.12, rib, x, H / 2, s * (W / 2 + 0.12)));     // corrugation
        [-1, 1].forEach(s => { box(0.5, H + 0.2, 0.5, rib, L / 2, H / 2, s * (W / 2 - 0.1)); box(0.5, H + 0.2, 0.5, rib, -L / 2, H / 2, s * (W / 2 - 0.1)); });   // corner posts
        box(0.5, 0.6, W, rib, L / 2, H - 0.2, 0); box(0.5, 0.5, W, rib, L / 2, 0.25, 0);                                          // door header + sill
        // the two end doors, swung open flat back against the outside (like the photo): bars + lock rods
        [-1, 1].forEach(s => {
            const piv = new THREE.Group(); piv.position.set(L / 2 + 0.2, 0, s * (W / 2)); piv.rotation.y = -s * 1.62; g.add(piv);
            box(0.18, H - 0.4, W / 2 - 0.1, shell, 0, H / 2, -s * (W / 4), piv);
            for (let k = 0; k < 4; k++) box(0.28, 0.25, W / 2 - 0.3, rib, 0.12, 1.4 + k * 1.75, -s * (W / 4), piv);
            [0.9, 2.4].forEach(dz => box(0.12, H - 0.6, 0.12, MAT.chrome || rib, 0.2, H / 2, -s * dz, piv));
        });
        // stencil on the side
        const sign = new THREE.Mesh(new THREE.PlaneGeometry(6, 1.5), new THREE.MeshBasicMaterial({ transparent: true, map: canvasTex(384, 96, (c, w, h) => {
            c.clearRect(0, 0, w, h); c.fillStyle = '#f8fafc'; c.font = 'bold 54px Arial, sans-serif'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText('STORAGE · 07', w / 2, h / 2);
        }) }));
        sign.position.set(0, H - 1.4, W / 2 + 0.2); g.add(sign);
        // racks along both long walls: steel uprights + 3 plywood shelves
        const steel = new THREE.MeshStandardMaterial({ color: 0x2f5d8a, roughness: 0.5, metalness: 0.4 }), shelf = new THREE.MeshStandardMaterial({ color: 0xc9a46a, roughness: 0.85 });
        const RD = 1.25, rack = s => {
            const z = s * (W / 2 - 0.3 - RD / 2);
            for (let x = -L / 2 + 0.6; x <= L / 2 - 2.6; x += 4) [-1, 1].forEach(e => box(0.14, 6.8, 0.14, steel, x, 3.4, z + e * (RD / 2 - 0.07)));
            [1.0, 3.2, 5.4].forEach(y => { box(L - 3.0, 0.12, RD, shelf, -1.3, y, z); box(L - 3.0, 0.12, 0.08, steel, -1.3, y - 0.12, z - s * (RD / 2 - 0.04)); });
            return z;
        };
        const zl = rack(-1), zr = rack(1);
        this.rackZ = [zl, zr];
        // tools on the left (south) rack: toolboxes, buckets, cable reels, gas cans, hard hats
        const colors = [0xc81e1e, 0xf97316, 0x1f2937, 0xfacc15, 0x2563eb];
        let n = 0;
        [1.0, 3.2, 5.4].forEach((y, row) => {
            for (let x = -L / 2 + 1.2; x < L / 2 - 4; x += 1.6 + ((n * 7) % 3) * 0.3) {
                const k = (n++ * 5 + row) % 5, c = colors[(n + row) % colors.length], m = new THREE.MeshStandardMaterial({ color: c, roughness: 0.6 });
                if (k === 0) { box(1.1, 0.55, 0.6, m, x, y + 0.34, zl); box(0.6, 0.08, 0.1, MAT.chrome || m, x, y + 0.66, zl); }                         // toolbox
                else if (k === 1) { const b = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.36, 0.85, 12), new THREE.MeshStandardMaterial({ color: 0xf97316, roughness: 0.6 })); b.position.set(x, y + 0.5, zl); g.add(b); }   // bucket
                else if (k === 2) { const r = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.55, 0.5, 14), new THREE.MeshStandardMaterial({ color: 0x8a5a2b, roughness: 0.8 })); r.rotation.x = Math.PI / 2; r.position.set(x, y + 0.6, zl); g.add(r); }  // cable reel
                else if (k === 3) { box(0.7, 0.75, 0.45, new THREE.MeshStandardMaterial({ color: 0xdc2626, roughness: 0.5 }), x, y + 0.45, zl); }                     // gas can
                else { const h = new THREE.Mesh(new THREE.SphereGeometry(0.38, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: 0xf4f4f1, roughness: 0.5 })); h.position.set(x, y + 0.08, zl); g.add(h); }   // hard hat
            }
        });
        // the delivery, once it's in: torque tubes + panel stacks on the empty rack and the rest of the shelves
        const fill = new THREE.Group(); fill.visible = false; g.add(fill); this.fill = fill;
        const tube = new THREE.MeshStandardMaterial({ color: 0xb8bdc2, roughness: 0.35, metalness: 0.75 }), pnl = new THREE.MeshStandardMaterial({ color: 0x1b2a4a, roughness: 0.3, metalness: 0.3 }), frm = new THREE.MeshStandardMaterial({ color: 0xc9ced3, roughness: 0.4, metalness: 0.6 });
        [3.2, 5.4].forEach(y => [-0.35, 0, 0.35].forEach((dz, k) => box(L - 3.6, 0.32, 0.32, tube, -1.3, y + 0.24 + (k === 1 ? 0.3 : 0), zr + dz, fill)));
        for (let x = -L / 2 + 1.8; x < L / 2 - 3.4; x += 3.6) { box(3.3, 0.9, 1.1, pnl, x, 1.0 + 0.52, zr, fill); box(3.36, 0.06, 1.14, frm, x, 1.0 + 0.98, zr, fill); }
        for (let x = L / 2 - 6.6; x < L / 2 - 3.2; x += 1.7) [1.0, 3.2, 5.4].forEach(y => box(1.5, 0.7, 1.05, pnl, x, y + 0.42, zl, fill));
        // colliders: walls + racks (player) and the walls + doors (vehicles too)
        const wb = (cx, cz, hx, hz, veh) => Boxes.add({ cx: STORE.x + cx, cz: STORE.z + cz, hx, hz, y0: y0 - 1, y1: y0 + H, player: true, vehicle: veh, tag: 'storage' });
        wb(-L / 2, 0, t / 2 + 0.1, W / 2, true); wb(0, -W / 2, L / 2, t / 2 + 0.1, true); wb(0, W / 2, L / 2, t / 2 + 0.1, true);
        wb(-1.3, zl, (L - 3.0) / 2, RD / 2, false); wb(-1.3, zr, (L - 3.0) / 2, RD / 2, false);
        [-1, 1].forEach(s => wb(L / 2 + 0.2 + W / 4, s * (W / 2 + 0.15), W / 4, 0.2, true));                        // the open doors
        // the deck is walkable: lift the floor so you step up into it
        Boxes.add({ cx: STORE.x, cz: STORE.z, hx: L / 2 - 0.2, hz: W / 2 - 0.3, y0: y0 - 1, y1: y0 + 0.2, player: true, walk: true, tag: 'storage-floor' });
        // where the 4 boxes end up (task points)
        this.slots = [L / 2 - 3.2, L / 2 - 7.4, L / 2 - 11.6, L / 2 - 15.8].map(dx => ({ x: STORE.x + dx, z: STORE.z }));
    },
    update() { if (this.fill) this.fill.visible = Build.has('panels'); },
};

// =====================================================================================================
// [BECKY]  Warehouse manager: stands outside the storage conex with her clipboard. Short lines when you're close.
// =====================================================================================================
const Becky = {
    rig: null, world: null, yaw: 0, t: 0, bubble: null, quipAt: 0, wasNear: false,
    IDLE: ["Can't wait for these packages.", 'Shoulda got same-day delivery.', "Inventory doesn't count itself.", 'Where IS that truck?', 'Sign here. And here. And here.'],
    AFTER: ['Racks are full. Love that for us.', 'Thanks again, hon.', 'Best delivery crew ever.', 'Panels are on the racks!'],
    init() {
        const r = buildSurveyor();
        applyLook(r, { g: 'f', s: 2, j: 0, gl: 4 });
        r.lookMats.hoodie.color.setHex(0x0e7490); r.lookMats.hoodieDark.color.setHex(0x0b5d73); r.lookMats.hair.color.setHex(0x8a5a2b);
        setRigPPE(r, 2 | 8);                                                  // hi-vis vest + safety glasses, no hard hat (hood down / ponytail)
        r.rod.visible = false; r.flags.visible = false;
        const clip = new THREE.Group(), cm = (w, h, d, c, x, y, z) => { const o = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), new THREE.MeshStandardMaterial({ color: c, roughness: 0.7 })); o.position.set(x, y, z); clip.add(o); };
        cm(0.9, 1.2, 0.05, 0x8b5a2b, 0, 0, 0); cm(0.78, 1.0, 0.02, 0xf8fafc, 0, -0.04, 0.035); cm(0.36, 0.1, 0.08, 0x9ca3af, 0, 0.56, 0.03);
        clip.position.set(0.05, -1.25, 0.36); clip.rotation.x = -1.2; r.armL.elbow.add(clip);
        r.armL.shoulder.rotation.set(-0.7, 0, 0.1); r.armL.elbow.rotation.x = -0.9;
        const x = STORE.x + STORE.L / 2 + 7.5, z = STORE.z + STORE.W / 2 + 4.0, y = getTerrainHeight(x, z);
        this.yaw = Math.PI * 0.62; r.group.position.set(x, y, z); r.group.rotation.y = this.yaw;
        scene.add(r.group); Colliders.add(x, z, 1.2, 8, { tag: 'npc' });
        this.rig = r; this.world = { x, y, z }; this.bubble = makeBubble('becky-bubble');
    },
    say(text, ms) { this.bubble.say(text, ms); },
    update(delta, now) {
        const r = this.rig; if (!r) return;
        this.t += delta;
        r.spine.rotation.x = Math.sin(this.t * 1.5) * 0.02;
        r.armR.shoulder.rotation.set(Math.sin(this.t * 0.7) * 0.15 - 0.1, 0, -0.08);                      // pen hand tapping the clipboard
        this.bubble.update(now, V(this.world.x, this.world.y + 7.0, this.world.z));
        const pp = playerGroup.position, d = flatDist(pp, this.world), near = d < 16 && !S.vehicle;
        let want = 0;
        if (d < 16) { const a = Math.atan2(pp.x - this.world.x, pp.z - this.world.z) - this.yaw; want = clamp(Math.atan2(Math.sin(a), Math.cos(a)), -1.0, 1.0); }
        r.head.rotation.y += (want - r.head.rotation.y) * Math.min(1, delta * 4);
        if (near && !this.wasNear && now > this.quipAt && !menusOpen()) {
            const t = Delivery.task();
            if (t && t.status === 'active' && !t.talked && !t.mirror) this.say('Hey! Over here — I need help!', 2400);
            else { const L = Build.has('panels') ? this.AFTER : this.IDLE; this.say(L[Math.floor(Math.random() * L.length)], 2600); }
            this.quipAt = now + 18000;
        }
        this.wasNear = near;
    },
    talk() {
        const t = Delivery.task(); SFX.blip();
        if (t && (t.status === 'active' || t.mirror) && !t.talked) {
            t.talked = true; Save.touch(); TaskManager.updateHud();
            this.say("My delivery semi flipped its trailer past the substation! Grab a forklift, bring all 4 boxes in here.", 6500);
            showToast('📦 Take a forklift (parked at the storage conex), drive east past the substation, and bring the 4 panel boxes into the conex.');
            return;
        }
        if (t && (t.status === 'active' || t.mirror)) { const p = TaskManager.progress(t); this.say(`${p.staked} of 4 in. Keep 'em coming!`, 2600); return; }
        const L = Build.has('panels') ? this.AFTER : this.IDLE; this.say(L[Math.floor(Math.random() * L.length)], 2600);
    },
};

// =====================================================================================================
// [DELIVERY]  The final job: the semi's flatbed tipped over out past the substation — 4 boxes of panels on the road.
//             Forklift them into the storage conex (box k goes to slot k = task point k). All 4 in → mission done,
//             Becky thanks you, panels go up on the racking piles, the conex racks fill up.
// =====================================================================================================
const WRECK = { x: 312, yaw: 0 };
const Delivery = {
    wreck: null, boxes: [], forklifts: [], BW: 4.2, BD: 3.0, BH: 3.0,
    task() { return TaskManager.get('T15'); },
    live() { const t = this.task(); return !!(t && ((t.status === 'active' && !t.mirror) || (TaskManager.mirror && TaskManager.mirror.rule.deliver))); },
    cur() { const m = TaskManager.mirror; return m && m.rule.deliver ? m : this.task(); },
    init() {
        // the wreck: tractor on the road shoulder, its flatbed tipped onto its side, 4 crates spilled toward the road
        const zc = roadCenterZ(WRECK.x), g = new THREE.Group(); scene.add(g); this.wreck = g; g.visible = false;
        Dozer.preclear((x, z) => x > WRECK.x - 52 && x < WRECK.x + 40 && z > zc - 22 && z < zc + 30);           // clear the trees there
        const L = (c, r = 0.6, m = 0.1) => new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: m });
        const red = L(0xb91c1c, 0.4, 0.3), blk = L(0x1a1b1d, 0.8), chrome = L(0xd7dbdf, 0.25, 0.9), glass = L(0x1e293b, 0.15, 0.4), deck = L(0x6b4a2f, 0.9), steel = L(0x2f3237, 0.6, 0.5), tire = L(0x111214, 0.95);
        const B = (w, h, d, m, x, y, z, par, rot) => { const o = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); o.position.set(x, y, z); if (rot) o.rotation.set(...rot); o.castShadow = true; par.add(o); return o; };
        const wheel = (par, x, y, z, r = 1.7) => { const w = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1.0, 16), tire); w.rotation.x = Math.PI / 2; w.position.set(x, y, z); w.castShadow = true; par.add(w);
            const h = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.5, r * 0.5, 1.05, 10), chrome); h.rotation.x = Math.PI / 2; h.position.copy(w.position); par.add(h); };
        // tractor: long hood, cab, sleeper, stacks, tanks, steer + tandem drive axles (faces +x, upright on the road)
        const tr = new THREE.Group(), tx = WRECK.x + 22, tz = zc + 2; tr.position.set(tx, getTerrainHeight(tx, tz), tz); g.add(tr);
        B(22, 1.0, 3.6, steel, -2, 2.2, 0, tr);                                                     // frame rails
        B(7.5, 3.4, 7.2, red, 6.8, 4.6, 0, tr); B(1.2, 2.8, 6.4, chrome, 10.8, 4.4, 0, tr);          // hood + grille
        B(5.2, 6.6, 8.0, red, 1.5, 6.2, 0, tr); B(0.1, 2.4, 6.8, glass, 4.15, 7.6, 0, tr, [0, 0, -0.35]);   // cab + windshield
        B(5.0, 7.6, 8.0, red, -3.6, 6.7, 0, tr);                                                     // sleeper
        [-1, 1].forEach(s => { B(0.5, 7.5, 0.5, chrome, -1.1, 9.0, s * 3.5, tr); B(3.4, 1.8, 1.8, chrome, 1.0, 3.0, s * 4.3, tr); B(0.2, 1.8, 1.4, glass, 1.5, 7.6, s * 4.05, tr); });
        B(3.4, 0.4, 6.0, steel, -9.5, 3.3, 0, tr);                                                    // fifth wheel (empty: the trailer broke off)
        B(1.0, 1.5, 8.6, chrome, 11.2, 2.6, 0, tr);                                                  // bumper
        [[7.8, 1.7], [-6.8, 1.7], [-11.2, 1.7]].forEach(([x, y]) => [-1, 1].forEach(s => wheel(tr, x, y, s * 3.6)));
        // flatbed trailer, tipped onto its right side behind the tractor: deck faces the road
        const tl = new THREE.Group(), lx = WRECK.x - 8, lz = zc + 14; tl.position.set(lx, getTerrainHeight(lx, lz) + 0.1, lz); tl.rotation.set(-Math.PI / 2 + 0.3, 0.06, 0); g.add(tl);
        B(48, 0.5, 8.4, deck, 0, 4.1, 0, tl); B(48, 1.6, 0.6, steel, 0, 3.0, -3.2, tl); B(48, 1.6, 0.6, steel, 0, 3.0, 3.2, tl);
        for (let k = -3; k <= 3; k++) B(48, 0.06, 0.12, L(0x4a321f, 0.9), 0, 4.37, k * 1.15, tl);                    // deck boards
        B(48, 0.7, 0.3, red, 0, 4.0, -4.3, tl); B(48, 0.7, 0.3, red, 0, 4.0, 4.3, tl);                            // red rub rails
        B(1.2, 2.2, 8.0, red, 23.4, 5.2, 0, tl);                                                                    // headboard
        for (let x = -22; x <= 22; x += 4) B(0.4, 0.8, 7.2, steel, x, 3.3, 0, tl);
        [[-17, 1.7], [-12.6, 1.7]].forEach(([x, y]) => [-1, 1].forEach(s => wheel(tl, x, y, s * 3.6)));
        B(2.4, 3.0, 0.4, steel, 20, 1.6, -2.4, tl); B(2.4, 3.0, 0.4, steel, 20, 1.6, 2.4, tl);         // landing gear
        for (let k = 0; k < 5; k++) { const s = B(0.12, 0.05, 7 + (k % 2) * 2, L(0xfacc15, 0.7), -18 + k * 9, 4.4, -1 - k * 0.6, tl); s.rotation.y = 0.3 * (k % 2 ? 1 : -1); }   // straps hanging loose
        // warning triangles + cones
        [[WRECK.x - 30, zc - 3], [WRECK.x + 38, zc - 3], [WRECK.x - 14, zc - 6]].forEach(([x, z]) => {
            const c = new THREE.Mesh(new THREE.ConeGeometry(0.55, 1.6, 10), L(0xf97316, 0.6)); c.position.set(x, getTerrainHeight(x, z) + 0.8, z); c.castShadow = true; g.add(c);
        });
        // (the wreck's solid only while it's out there: invisible semi = nothing to bump into)
        this.wcols = [Colliders.add(tx + 2, tz, 4.6, 10, { tag: 'semi' }), Colliders.add(tx + 8, tz, 4.4, 10, { tag: 'semi' }), Colliders.add(tx - 6, tz, 4.4, 10, { tag: 'semi' })];
        for (let x = lx - 22; x <= lx + 22; x += 7) this.wcols.push(Colliders.add(x, lz, 4.5, 6, { tag: 'semi' }));
        this.wcols.forEach(c => { c.r0 = c.r; c.top0 = c.top; }); this.solid(false);
        // the 4 crates: pallet + big cardboard box with a label, strapped
        const cardboard = L(0xc7a36b, 0.95), pallet = L(0x8a6a45, 0.9), strap = L(0x111111, 0.6);
        const label = new THREE.MeshBasicMaterial({ map: canvasTex(256, 160, (c, w, h) => {
            c.fillStyle = '#e8d5ac'; c.fillRect(0, 0, w, h); c.fillStyle = '#1e293b'; c.font = 'bold 34px Arial'; c.textAlign = 'center';
            c.fillText('SOLAR PANELS', w / 2, 50); c.font = 'bold 22px Arial'; c.fillText('30 MODULES · 550 W', w / 2, 88); c.fillStyle = '#b91c1c'; c.fillText('⬆ THIS SIDE UP ⬆', w / 2, 128);
        }) });
        const spill = [[WRECK.x - 18, zc + 3, 0.4], [WRECK.x - 6, zc + 1, -0.3], [WRECK.x + 4, zc + 4.5, 0.9], [WRECK.x - 26, zc - 1, 1.3]];
        for (let k = 0; k < 4; k++) {
            const b = new THREE.Group(), { BW, BD, BH } = this;
            B(BW + 0.2, 0.45, BD + 0.2, pallet, 0, 0.22, 0, b); B(BW, BH, BD, cardboard, 0, 0.45 + BH / 2, 0, b);
            [-1, 1].forEach(s => B(0.08, BH + 0.06, BD + 0.04, strap, s * BW / 3, 0.45 + BH / 2, 0, b));
            const lb = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 1.5), label); lb.position.set(0, 0.45 + BH / 2, BD / 2 + 0.02); b.add(lb);
            const lb2 = lb.clone(); lb2.rotation.y = Math.PI; lb2.position.z = -BD / 2 - 0.02; b.add(lb2);
            const [x, z, yaw] = spill[k];
            const home = { x, z, yaw, tilt: k === 3 ? 0.18 : 0 };
            scene.add(b); b.visible = false;
            this.boxes.push({ g: b, k, home, state: 'ground', x, z, yaw });
        }
        this.placeHome();
    },
    solid(on) {
        if (this.wcolOn === on || !this.wcols) return; this.wcolOn = on;
        this.wcols.forEach(c => { c.r = on ? c.r0 : 0; c.top = on ? c.top0 : -1e9; c.ghost = !on; });
    },
    placeHome() {
        this.boxes.forEach(b => { if (b.state !== 'ground') return; b.x = b.home.x; b.z = b.home.z; b.yaw = b.home.yaw; this.put(b); b.g.rotation.z = b.home.tilt; });
    },
    put(b) { b.g.position.set(b.x, Storage.inside(b.x, b.z, 0.5) ? getTerrainHeight(STORE.x, STORE.z) + 0.2 : getTerrainHeight(b.x, b.z), b.z); b.g.rotation.set(0, b.yaw, 0); },
    // fork centre (world) of a forklift
    forkPoint(v) { const p = v.forks.localToWorld(V(0, 0, 2.0)); return p; },
    nearestBox(v) {
        const p = this.forkPoint(v); let best = null, bd = 3.0;
        this.boxes.forEach(b => { if (b.state !== 'ground' || b.remote) return; const d = Math.hypot(b.x - p.x, b.z - p.z); if (d < bd) { bd = d; best = b; } });
        return best;
    },
    // what the use button does from the forklift seat
    forkAction(v) {
        if (!this.live()) return null;
        if (v.carry >= 0) {
            const p = this.forkPoint(v), inside = Storage.inside(p.x, p.z, 2.0);
            return { kind: 'grab', short: 'DROP', label: inside ? 'Set the box down in the storage conex' : 'Set the box down here', act: () => this.drop(v) };
        }
        const b = this.nearestBox(v);
        return b ? { kind: 'grab', short: 'LIFT', label: 'Lift the panel box', act: () => this.lift(v, b) } : null;
    },
    lift(v, b) {
        b.state = 'carried'; b.by = v; v.carry = b.k; b.g.rotation.set(0, 0, 0);
        v.forks.add(b.g); b.g.position.set(0, 0.12, 1.95); b.g.rotation.set(0, Math.PI / 2, 0);
        SFX.blip(); Net.force = true; showToast('📦 Got one — bring it to the storage conex behind the break room.');
    },
    drop(v) {
        const b = this.boxes[v.carry]; if (!b) { v.carry = -1; return; }
        const p = this.forkPoint(v); v.forks.remove(b.g); scene.add(b.g); v.carry = -1; b.by = null;
        if (Storage.inside(p.x, p.z, 2.0)) { this.storeLocal(b, p); return; }
        b.state = 'ground'; b.x = p.x; b.z = p.z; b.yaw = v.group.rotation.y + Math.PI / 2; this.put(b); SFX.thud(0.4); Net.force = true;
    },
    // a box made it into the conex: slide it to its slot; tell the lead if I'm helping
    storeLocal(b, from) {
        const t = this.cur(); if (!t) return;
        this.slide(b, from);
        if (t.mirror) { t.pending[b.k] = performance.now(); Net.emit('dv', b.k); TaskManager.markVertex(t, b.k, null, true); TaskManager.updateHud(); return; }
        this.markStored(t, b.k);
    },
    slide(b, from) {
        b.state = 'stored'; const s = Storage.slots[b.k], y = getTerrainHeight(STORE.x, STORE.z) + 0.2, a = { x: from ? from.x : b.x, z: from ? from.z : b.z };
        b.g.rotation.set(0, Math.PI / 2, 0); SFX.thud(0.5);
        Anims.push({ age: 0, dur: 0.8, step: tt => { const u = clamp(tt / 0.8, 0, 1), e = 1 - Math.pow(1 - u, 3); b.g.position.set(a.x + (s.x - a.x) * e, y, a.z + (s.z - a.z) * e); }, done: () => { b.x = s.x; b.z = s.z; b.g.position.set(s.x, y, s.z); } });
    },
    markStored(t, k) {
        if (t.stakedFlags[k]) return;
        TaskManager.markVertex(t, k, null, true);
        const p = TaskManager.progress(t); TaskManager.updateHud(); Save.touch(); Net.force = true;
        Becky.say(p.staked >= p.total ? 'That\'s all four! THANK you!' : `${p.staked} of 4 in. Keep 'em coming!`, 3000);
        if (p.staked >= p.total) {
            TaskManager.complete(t); t.built = true;
            setTimeout(() => { Build.runFor('T15', true); Becky.say('Panels are going up on the racks now!', 3200); }, 1500);
        }
    },
    // helper → lead: a box went in on their screen
    remoteStore(k) {
        const t = this.task(); if (!t || t.status !== 'active' || t.mirror || k < 0 || k > 3) return;
        const b = this.boxes[k]; if (b.state === 'carried' && b.by) { b.by.forks.remove(b.g); scene.add(b.g); b.by.carry = -1; b.by = null; }
        if (b.state !== 'stored') this.slide(b, null);
        this.markStored(t, k);
    },
    // Settings › Debug › Complete mission
    finishAll() {
        const t = this.cur(); if (!t) return;
        this.forklifts.forEach(v => { if (v.carry >= 0) { const b = this.boxes[v.carry]; v.forks.remove(b.g); scene.add(b.g); v.carry = -1; b.by = null; } });
        if (!t.talked) t.talked = true;
        this.boxes.forEach(b => { if (b.state !== 'stored') { this.slide(b, null); if (t.mirror) { Net.emit('dv', b.k); TaskManager.markVertex(t, b.k, null, true); } else this.markStored(t, b.k); } });
    },
    update(delta, now) {
        const t = this.cur(), on = this.live();
        this.wreck.visible = !!(on || (t && t.status === 'active')); this.solid(this.wreck.visible);
        // boxes: shown while the job is on; stored ones follow the task flags (load / crew sync); after the job they're unpacked onto the racks
        const done = !on && !!t && t.status === 'completed';
        this.boxes.forEach(b => {
            b.g.visible = on || done;                                   // only out on the road during the job; afterwards they sit in the conex
            if (done && !b.parked) {
                if (b.state === 'carried' && b.by) { b.by.forks.remove(b.g); scene.add(b.g); b.by.carry = -1; b.by = null; }
                const sl = Storage.slots[b.k]; b.state = 'stored'; b.parked = true;
                if (!b.sliding) { b.g.position.set(sl.x, getTerrainHeight(STORE.x, STORE.z) + 0.2, sl.z); b.g.rotation.set(0, Math.PI / 2, 0); }
            }
            if (!done) b.parked = false;
            if (!on) return;
            if (t.stakedFlags[b.k] && b.state !== 'stored' && !(b.state === 'carried' && b.by === S.vehicle)) {
                if (b.state === 'carried' && b.by) { b.by.forks.remove(b.g); scene.add(b.g); b.by.carry = -1; b.by = null; }
                this.slide(b, null);
            } else if (!t.stakedFlags[b.k] && b.state === 'stored' && !(t.pending && now - (t.pending[b.k] || -1e9) < 4000)) { b.state = 'ground'; this.placeHome(); }
        });
        // crewmates' forklifts: show the box they're carrying on their forks
        if (on && Net.on) {
            this.boxes.forEach(b => { b.remote = false; });
            Net.remotes.forEach(R => {
                const fk = R.pres && R.pres.fk; if (!Array.isArray(fk)) return;
                const v = this.forklifts.find(f => f.name === fk[0]), b = this.boxes[fk[1] | 0];
                if (!v || !b || b.state === 'stored' || (b.by && b.by !== v)) return;
                b.remote = true;
                if (b.g.parent !== v.forks) { v.forks.add(b.g); b.g.position.set(0, 0.12, 1.95); b.g.rotation.set(0, Math.PI / 2, 0); b.state = 'carried'; b.by = v; }
            });
            this.boxes.forEach(b => { if (b.state === 'carried' && b.by && b.by !== S.vehicle && b.by.carry !== b.k && !b.remote) { b.by.forks.remove(b.g); scene.add(b.g); b.state = 'ground'; b.by = null; this.placeHome(); } });
        }
        // forks ride up while carrying, down when empty
        this.forklifts.forEach(v => {
            const want = (v.carry >= 0 || this.boxes.some(b => b.by === v)) ? 1.6 : 0.45;
            v.forkH += (want - v.forkH) * Math.min(1, delta * 3); v.forks.position.y = v.forkH;
            v.beacon.material.color.setHex(Math.sin(now * 0.012) > 0 ? 0xffa21a : 0x7a4a08);
        });
    },
    // minimap: the wreck + loose boxes
    drawRadar(focus, sc, R) {
        if (!this.live()) return;
        const t = this.cur();
        rCtx.fillStyle = '#facc15'; rCtx.strokeStyle = 'rgba(0,0,0,0.7)'; rCtx.lineWidth = 1;
        this.boxes.forEach(b => {
            if (t && t.stakedFlags[b.k]) return;
            let x = (b.x - focus.x) * sc, y = (b.z - focus.z) * sc;
            if (b.state === 'carried' && b.by) { const p = b.by.group.position; x = (p.x - focus.x) * sc; y = (p.z - focus.z) * sc; }
            const d = Math.hypot(x, y); if (d > R) { x *= R / d; y *= R / d; }
            rCtx.fillRect(x - 3, y - 3, 6, 6); rCtx.strokeRect(x - 3, y - 3, 6, 6);
        });
    },
};

// =====================================================================================================
// [PAINT]  Spray paint (job box, any ribbon colour; tap the slot again to change colour). Tap to spray the ground:
//          the dots fade after a few seconds. Spray a crewmate in the face and their screen gets splattered.
// =====================================================================================================
const Spray = {
    MAX: 700, sent: 0, LIFE: 4500, FADE: 1500, mesh: null, dots: [], n: 0, until: 0, acc: 0, buf: [], sendAt: 0, hitAt: {}, can: null,
    init() {
        const geo = new THREE.CircleGeometry(0.42, 10); geo.rotateX(-Math.PI / 2);
        const m = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.92, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3 });
        const mesh = new THREE.InstancedMesh(geo, m, this.MAX); mesh.frustumCulled = false; mesh.count = this.MAX;
        const o = new THREE.Object3D(); o.scale.setScalar(0.0001); o.updateMatrix();
        for (let i = 0; i < this.MAX; i++) { mesh.setMatrixAt(i, o.matrix); mesh.setColorAt(i, new THREE.Color(0xffffff)); }
        scene.add(mesh); this.mesh = mesh; this.o = o; this.col = new THREE.Color();
        // the can in your right hand (shown while it's out)
        const can = new THREE.Group(), body = new THREE.Mesh(new THREE.CylinderGeometry(0.17, 0.17, 0.7, 12), new THREE.MeshStandardMaterial({ color: 0xff2222, roughness: 0.4, metalness: 0.3 }));
        const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.13, 0.16, 10), new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.6 })); cap.position.y = 0.43;
        can.add(body, cap); can.position.set(0.02, -1.25, 0.22); can.rotation.x = -0.5; can.visible = false; rig.armR.elbow.add(can);
        this.can = can; this.canMat = body.material;
    },
    has() { return !!(S.paint && S.paint.has); },
    color() { return flagColorOptions[(S.paint && S.paint.c) | 0] || flagColorOptions[4]; },
    // a burst from the can (each tap ~half a second)
    burst() {
        if (!this.has()) return;
        if (Trees.tryPaint()) return;                                    // standing at a tree that needs an X: that's what the paint is for
        this.until = performance.now() + 480; SFX.spray && SFX.spray();
    },
    add(x, z, ci, now) {
        const i = this.n++ % this.MAX, y = supportHeight(x, z, 0.3, playerGroup.position.y + 0.6) + 0.2, s = 0.55 + Math.random() * 0.7;
        this.dots[i] = { x, y, z, born: now, s };
        this.o.position.set(x, y, z); this.o.rotation.set(0, Math.random() * 6.28, 0); this.o.scale.setScalar(s); this.o.updateMatrix();
        this.mesh.setMatrixAt(i, this.o.matrix); this.mesh.setColorAt(i, this.col.setHex(flagColorOptions[ci].hex));
        this.mesh.instanceMatrix.needsUpdate = true; if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
    },
    update(delta, now) {
        if (!this.mesh) return;
        const out = !!(S.paintOut && this.has() && !S.driving && !S.seat && !S.dead);
        if (this.can) { this.can.visible = out; if (out) this.canMat.color.setHex(this.color().hex); }
        if (out && now < this.until) {
            rig.armR.shoulder.rotation.set(-1.35, 0, -0.1); rig.armR.elbow.rotation.x = -0.2;      // arm out, pointing the can down
            this.acc += delta;
            const P = playerGroup.position, yw = playerGroup.rotation.y, fx = Math.sin(yw), fz = Math.cos(yw), ci = (S.paint.c | 0);
            while (this.acc > 0.024) {
                this.acc -= 0.024;
                const d = 3.2 + Math.random() * 0.5, j = () => (Math.random() - 0.5) * 0.6;
                const x = P.x + fx * d + j(), z = P.z + fz * d + j();
                this.add(x, z, ci, now); if ((++this.sent % 3) === 0 && this.buf.length < 16) this.buf.push(Math.round(x * 10) / 10, Math.round(z * 10) / 10);
            }
            // a crewmate right in front of the nozzle gets it in the face
            if (Net.on) Net.remotes.forEach(R => {
                if (!R.pos || R.veh) return;
                const dx = R.pos.x - P.x, dz = R.pos.z - P.z, d = Math.hypot(dx, dz);
                if (d > 5.5 || d < 0.1 || (dx * fx + dz * fz) / d < 0.55) return;
                if (now < (this.hitAt[R.peer] || 0)) return;
                this.hitAt[R.peer] = now + 1500; Net.emit('ss', R.peer, ci); Pow.show(V(R.pos.x, R.pos.y + 5.5, R.pos.z), 'SPLAT!', false);
            });
        }
        if (this.buf.length && now > this.sendAt) { this.sendAt = now + 400; Net.emit('sp', S.paint.c | 0, this.buf.slice(0, 16)); this.buf = []; }
        // fade: shrink away at the end of their life
        let dirty = false;
        for (let i = 0; i < this.dots.length; i++) {
            const d = this.dots[i]; if (!d || d.dead) continue;
            const age = now - d.born; if (age < this.LIFE) continue;
            const k = 1 - (age - this.LIFE) / this.FADE;
            if (k <= 0) { d.dead = true; this.o.scale.setScalar(0.0001); } else { this.o.scale.setScalar(d.s * k); }
            this.o.position.set(d.x, d.y, d.z); this.o.rotation.set(0, 0, 0); this.o.updateMatrix(); this.mesh.setMatrixAt(i, this.o.matrix); dirty = true;
        }
        if (dirty) this.mesh.instanceMatrix.needsUpdate = true;
    },
    // someone else's spray (Net 'sp')
    remote(ci, flat) {
        const now = performance.now(); ci = clamp(ci | 0, 0, flagColorOptions.length - 1);
        if (Array.isArray(flat)) for (let i = 0; i + 1 < flat.length && i < 32; i += 2) for (let k = 0; k < 3; k++) this.add((+flat[i] || 0) + (Math.random() - 0.5) * 0.9, (+flat[i + 1] || 0) + (Math.random() - 0.5) * 0.9, ci, now);
    },
    // you got sprayed: paint splats over your screen for a couple of seconds
    splash(ci) {
        const c = flagColorOptions[clamp(ci | 0, 0, flagColorOptions.length - 1)].css;
        let el = $('paint-splash');
        if (!el) { el = document.createElement('div'); el.id = 'paint-splash'; document.body.appendChild(el); }
        el.innerHTML = '';
        for (let k = 0; k < 9; k++) {
            const b = document.createElement('i'), s = 30 + Math.random() * 45;
            b.style.cssText = `left:${Math.random() * 90 - 5}%;top:${Math.random() * 90 - 5}%;width:${s}vmin;height:${s * (0.8 + Math.random() * 0.4)}vmin;background:${c};transform:rotate(${Math.random() * 360}deg)`;
            el.appendChild(b);
        }
        el.classList.remove('on'); void el.offsetWidth; el.classList.add('on');
        SFX.thud && SFX.thud(0.3); showToast('🎨 You got sprayed!');
    },
};

// =====================================================================================================
// [TREES]  Drone photos show trees in the panel rows. Mission: spray a red X on each marked tree (the RTK rod beeps you
//          to them; a little minigame where you paint the X yourself). Report to Justin → the tree crew drops every
//          tree that would sit in the panels (Build stage 'trees'), then it's on to Becky's delivery.
// =====================================================================================================
const Trees = {
    decals: new Map(), beepAt: 0, xTex: null,
    // every standing tree whose trunk or crown would end up in a panel row
    conflicts() {
        const R = Plan.rack(); if (!R.rows || !R.rows.length) return [];
        const rows = R.rows.map(row => { const a = R.piles[row[0]], b = R.piles[row[row.length - 1]]; return { x: a.x, z0: Math.min(a.z, b.z) - 4, z1: Math.max(a.z, b.z) + 4 }; });
        return FOLIAGE.filter(it => it.kind === 'tree' && !it.gone && rows.some(r => Math.abs(it.x - r.x) < 10.5 && it.z > r.z0 && it.z < r.z1));
    },
    // the ones Justin wants marked (closest to the yard first, 10 at most)
    targets() { return this.conflicts().sort((a, b) => Math.hypot(a.x, a.z + 40) - Math.hypot(b.x, b.z + 40)).slice(0, 10).map(it => ({ x: it.x, z: it.z })); },
    task() { const m = TaskManager.mirror; if (m && m.rule.mark) return m; const t = TaskManager.get('T14'); return t && t.status === 'active' ? t : null; },
    nearestOpen(pos, r = 5) {
        const t = this.task(); if (!t) return -1;
        let best = -1, bd = r;
        t.points.forEach((p, i) => { if (t.stakedFlags[i]) return; const d = Math.hypot(p.x - pos.x, p.z - pos.z); if (d < bd) { bd = d; best = i; } });
        return best;
    },
    // use button (F) next to a target tree
    useAt(pos) {
        const i = this.nearestOpen(pos, 5.2); if (i < 0) return null;
        const t = this.task(), d = Math.hypot(t.points[i].x - pos.x, t.points[i].z - pos.z);
        if (!Spray.has()) return { d, t: { kind: 'grab', short: 'PAINT', label: 'Marked tree — grab red spray paint from the job box behind the break room', act: () => showToast('🎨 Red spray paint is in the job box behind the break room.') } };
        return { d, t: { kind: 'grab', short: 'PAINT X', label: 'Spray a red X on this tree', act: () => this.start(i) } };
    },
    // spraying (click / SPRAY) right at a target tree starts the X too
    tryPaint() { const i = this.nearestOpen(playerGroup.position, 5.2); if (i < 0) return false; this.start(i); return true; },
    start(i) {
        const t = this.task(); if (!t || t.stakedFlags[i]) return;
        if ((S.paint.c | 0) !== 4) { S.warn = { text: 'Justin said RED paint — tap the spray paint slot again to switch colours.', until: performance.now() + 2600 }; return; }
        S.paintOut = true; Hotbar.refresh && Hotbar.refresh();
        XPaint.open(() => this.mark(t, i));
    },
    mark(t, i) {
        if (t.stakedFlags[i]) return;
        SFX.vertexOk && SFX.vertexOk();
        if (t.mirror) { t.pending[i] = performance.now(); Net.emit('tx', i); TaskManager.markVertex(t, i, null, true); TaskManager.updateHud(); return; }
        TaskManager.markVertex(t, i, null, true);
        const p = TaskManager.progress(t); TaskManager.updateHud(); Save.touch();
        setHTML('delta-box', `TREE MARKED ${p.staked}/${p.total}`);
        if (p.staked >= p.total) TaskManager.complete(t);
    },
    remoteMark(i) { const t = TaskManager.get('T14'); if (!t || t.status !== 'active' || t.mirror || i < 0 || i >= t.points.length) return; this.mark(t, i); },
    // the X on the trunk, facing the yard
    decal(p, key) {
        if (this.decals.has(key)) return;
        if (!this.xTex) this.xTex = canvasTex(128, 128, (c, w, h) => { c.clearRect(0, 0, w, h); c.strokeStyle = '#ff2222'; c.lineWidth = 18; c.lineCap = 'round'; c.beginPath(); c.moveTo(22, 20); c.lineTo(106, 108); c.moveTo(108, 22); c.lineTo(20, 106); c.stroke(); });
        const it = FOLIAGE.find(f => f.kind === 'tree' && Math.abs(f.x - p.x) < 0.2 && Math.abs(f.z - p.z) < 0.2), r = it && it.col ? Math.max(0.6, it.col.r - 0.1) : 0.9;
        const a = Math.atan2(-p.x, -40 - p.z), m = new THREE.Mesh(new THREE.PlaneGeometry(1.8, 1.8), new THREE.MeshBasicMaterial({ map: this.xTex, transparent: true, depthWrite: false, side: THREE.DoubleSide }));
        m.position.set(p.x + Math.sin(a) * (r + 0.05), getTerrainHeight(p.x, p.z) + 4.6, p.z + Math.cos(a) * (r + 0.05)); m.rotation.y = a;
        scene.add(m); this.decals.set(key, m);
    },
    clearDecals() { this.decals.forEach(m => scene.remove(m)); this.decals.clear(); },
    update(delta, now) {
        const t = this.task();
        // decals follow the task flags (works for crew helpers too)
        if (t) t.points.forEach((p, i) => { if (t.stakedFlags[i]) this.decal(p, Math.round(p.x * 10) + ',' + Math.round(p.z * 10)); });
        if (Build.has('trees') && this.decals.size) this.clearDecals();
        // the rod "finds" the trees: beeps faster as you close in, readout above the hotbar
        if (!t || S.driving || Hotbar.current() !== 2) return;
        let bd = 1e9, bp = null; const P = playerGroup.position;
        t.points.forEach((p, i) => { if (t.stakedFlags[i]) return; const d = Math.hypot(p.x - P.x, p.z - P.z); if (d < bd) { bd = d; bp = p; } });
        if (!bp || bd > 90) return;
        if (now > this.beepAt) {
            this.beepAt = now + clamp(bd * 22, 110, 1600);
            try { const ctx = SFX.ctx(); if (ctx) SFX.tone(ctx, ctx.currentTime, { type: 'square', from: bd < 6 ? 1500 : 1100, len: 0.05, vol: 0.06 }); } catch (e) { /* audio off */ }
            const dirs = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'], ang = Math.atan2(bp.x - P.x, -(bp.z - P.z));
            setHTML('delta-box', `🌲 Marked tree <b>${Math.round(bd)} ft</b> ${dirs[((Math.round(ang / (Math.PI / 4)) % 8) + 8) % 8]}${bd < 6 ? ' — spray the X!' : ''}`);
        }
    },
};

// paint-the-X minigame: two strokes corner to corner, crossing
const XPaint = {
    el: null, cb: null, strokes: [], cur: null,
    build() {
        const el = document.createElement('div'); el.id = 'xpaint'; el.hidden = true;
        el.innerHTML = '<div class="xp-card"><div class="xp-t">PAINT THE X</div><div class="xp-s">Two strokes, corner to corner — drag with your finger or mouse.</div><canvas width="320" height="320"></canvas><div class="xp-b"><button data-x="clear">Wipe</button><button data-x="cancel">Cancel</button></div></div>';
        document.body.appendChild(el); this.el = el; this.cv = el.querySelector('canvas'); this.c = this.cv.getContext('2d');
        const pos = e => { const r = this.cv.getBoundingClientRect(); return { x: (e.clientX - r.left) * 320 / r.width, y: (e.clientY - r.top) * 320 / r.height }; };
        this.cv.addEventListener('pointerdown', e => { e.preventDefault(); try { this.cv.setPointerCapture(e.pointerId); } catch (er) { /* ok */ } this.cur = [pos(e)]; SFX.spray && SFX.spray(); });
        this.cv.addEventListener('pointermove', e => { if (!this.cur) return; const p = pos(e), q = this.cur[this.cur.length - 1]; this.cur.push(p); this.ink(q, p); });
        const up = () => { if (!this.cur) return; this.strokes.push(this.cur); this.cur = null; this.check(); };
        this.cv.addEventListener('pointerup', up); this.cv.addEventListener('pointercancel', up);
        el.querySelector('[data-x=clear]').addEventListener('click', () => this.reset());
        el.querySelector('[data-x=cancel]').addEventListener('click', () => this.close(false));
        ['touchstart', 'touchmove', 'mousedown', 'keydown'].forEach(ev => el.addEventListener(ev, e => e.stopPropagation(), { passive: true }));
    },
    bark() {
        const c = this.c; c.fillStyle = '#5b3d26'; c.fillRect(0, 0, 320, 320);
        for (let i = 0; i < 26; i++) { c.fillStyle = i % 2 ? '#4a301d' : '#6b4a30'; c.fillRect(i * 12.3 + (i % 3) * 2, 0, 5 + (i % 4), 320); }
        c.strokeStyle = 'rgba(0,0,0,0.25)'; c.lineWidth = 2; for (let y = 20; y < 320; y += 37) { c.beginPath(); c.moveTo(0, y); c.lineTo(320, y + 8); c.stroke(); }
    },
    ink(a, b) { const c = this.c; c.strokeStyle = '#ff2222'; c.lineWidth = 20; c.lineCap = 'round'; c.globalAlpha = 0.85; c.beginPath(); c.moveTo(a.x, a.y); c.lineTo(b.x, b.y); c.stroke(); c.globalAlpha = 1; },
    reset() { this.strokes = []; this.cur = null; this.bark(); },
    open(cb) {
        if (!this.el) this.build();
        this.cb = cb; this.reset(); this.el.hidden = false; S.miniGame = true;
        if (document.pointerLockElement) document.exitPointerLock();
    },
    close(ok) {
        this.el.hidden = true; S.miniGame = false;
        const cb = this.cb; this.cb = null;
        if (ok && cb) cb();
        if (!Touch.active) { try { lockPointer(); } catch (e) { /* needs a click */ } }
    },
    // good X = two long diagonal strokes going opposite ways that cross near the middle
    check() {
        const diag = s => { const a = s[0], b = s[s.length - 1], dx = b.x - a.x, dy = b.y - a.y; return { ok: Math.abs(dx) > 120 && Math.abs(dy) > 120, slope: Math.sign(dx) * Math.sign(dy), mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2 }; };
        const good = this.strokes.map(diag).filter(d => d.ok);
        const hasBoth = good.some(d => d.slope > 0) && good.some(d => d.slope < 0);
        if (hasBoth) { setTimeout(() => this.close(true), 280); showToast('❌ Nice X — that tree is coming down.'); return; }
        if (this.strokes.length >= 4) { showToast('Not quite an X — corner to corner, two strokes.'); this.reset(); }
    },
};

// =====================================================================================================
// [HUM]  Once the panels are up, the inverter skid and the substation hum (they're taking power)
// =====================================================================================================
const PowerHum = {
    srcs: null, NEAR: 8, FAR: 55,               // full volume within 8 ft of the gear, silent past 55 ft
    // one hum voice: mains buzz (60 Hz family + a filtered sawtooth so phone speakers can play it too), slow swell
    voice(ctx, base, buzz) {
        const bus = ctx.createGain(); bus.gain.value = 0; bus.connect(SFX.bus);
        const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 900; lp.connect(bus);
        [[base, 0.45], [base * 2, 0.3], [base * 3, 0.14]].forEach(([f, g]) => { const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = f; const gg = ctx.createGain(); gg.gain.value = g; o.connect(gg).connect(lp); o.start(); });
        const sw = ctx.createOscillator(); sw.type = 'sawtooth'; sw.frequency.value = buzz;
        const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = buzz * 3; bp.Q.value = 4;
        const sg = ctx.createGain(); sg.gain.value = 0.16; sw.connect(bp).connect(sg).connect(lp); sw.start();
        const lfo = ctx.createOscillator(), lg = ctx.createGain(); lfo.frequency.value = 0.3 + Math.random() * 0.2; lg.gain.value = 0.05; lfo.connect(lg).connect(sg.gain); lfo.start();
        return bus;
    },
    update() {
        const on = Build.has('panels');
        if (!on && !this.srcs) return;
        const ctx = SFX.ctx(); if (!ctx) return;
        if (!this.srcs) this.srcs = { inv: this.voice(ctx, 120, 120), sub: this.voice(ctx, 60, 180) };     // inverter: higher whine · substation: deep transformer hum
        const P = S.vehicle ? S.vehicle.group.position : playerGroup.position, I = Plan.get().inv;      // (in a buggy your body's position is seat-local)
        const k = d => { const u = clamp(1 - (d - this.NEAR) / (this.FAR - this.NEAR), 0, 1); return u * u; };
        const dInv = I ? Math.hypot(Math.max(Math.abs(P.x - I.x) - I.padW / 2, 0), Math.max(Math.abs(P.z - I.z) - I.padD / 2, 0)) : 1e9;
        const amb = Ambience.volume / 14;
        this.srcs.inv.gain.setTargetAtTime(on ? 0.12 * k(dInv) * amb : 0, ctx.currentTime, 0.25);
        this.srcs.sub.gain.setTargetAtTime(on ? 0.14 * k(subRectDist(P.x, P.z)) * amb : 0, ctx.currentTime, 0.25);
    },
};

// =====================================================================================================
// [ISLAND]  Walk or drive off the beach into deep water and you drown: back to the yard. Anything left floating
//           out there (a UTV you bailed out of) gets towed back to its parking spot.
// =====================================================================================================
const Island = {
    DEEP: 1.6, next: 0,
    deep(p) { return shoreDist(p.x, p.z) < 10 && getTerrainHeight(p.x, p.z) < CONFIG.world.sea - this.DEEP; },
    home(v) {
        const sp = v.cfg && v.cfg.spawn; if (!sp) return;
        v.group.position.set(sp.x, 0, sp.z); v.group.rotation.set(0, sp.yaw || 0, 0); v.speed = 0; settleOnTerrain(v, 1);
        showToast(`🛟 ${v.cfg.label || 'The vehicle'} got towed back to the yard.`);
    },
    tick(now) {
        if (S.title) return;
        if (!S.dead && !S.pass) {
            const v = S.driving ? S.vehicle : null, p = v ? v.group.position : playerGroup.position;
            if (this.deep(p)) {
                S.hurtBy = 'water'; Net.lastHitBy = null;
                if (v) { handleVehicleToggle(); this.home(v); }
                SFX.thud && SFX.thud(0.6);
                Vitals.die();
            }
        }
        if (now < this.next) return; this.next = now + 1000;
        VEHICLES.forEach(o => { if (!o.parked && o !== S.vehicle && !o.remoteBy && this.deep(o.group.position)) this.home(o); });
    },
};

// =====================================================================================================
// [FULLSCREEN]  Settings › Full screen. Uses the browser's Fullscreen API where the page is allowed to (Android,
//               desktop, iPad). iPhone browsers / in-app viewers don't let a web page take over the whole screen,
//               so there it says so instead of silently doing nothing.
// =====================================================================================================
const FullScreen = {
    el() { return document.fullscreenElement || document.webkitFullscreenElement || null; },
    can() { const d = document.documentElement; return !!((d.requestFullscreen || d.webkitRequestFullscreen) && (document.fullscreenEnabled || document.webkitFullscreenEnabled)); },
    label() { setText('fs-state', this.el() ? 'ON' : 'OFF'); const b = $('dev-fs'); if (b) b.classList.toggle('on', !!this.el()); },
    async toggle() {
        try {
            if (this.el()) { await (document.exitFullscreen ? document.exitFullscreen() : document.webkitExitFullscreen()); }
            else if (this.can()) { const d = document.documentElement; await (d.requestFullscreen ? d.requestFullscreen({ navigationUI: 'hide' }) : d.webkitRequestFullscreen()); try { if (screen.orientation && screen.orientation.lock) await screen.orientation.lock('landscape'); } catch (e) { /* not allowed: fine */ } }
            else if (navigator.standalone || (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)) showToast("✅ You're already full screen — this is the home-screen app.");
            else if (/iPhone|iPod/.test(navigator.userAgent)) showToast(window.claude && window.claude.hosted ? '📱 For full screen on iPhone: tap Share → Add to Home Screen, then open the game from its icon.' : "📱 iPhone doesn't let web pages go full screen inside the Claude app. Turn your phone sideways for the biggest view.");
            else { showToast("This browser won't let the game go full screen here."); }
        } catch (e) { showToast("Full screen was blocked here — try again, or turn your phone sideways."); }
        setTimeout(() => this.label(), 300);
    },
    init() {
        const b = $('dev-fs'); if (b) b.addEventListener('click', e => { e.stopPropagation(); this.toggle(); });
        ['fullscreenchange', 'webkitfullscreenchange'].forEach(ev => document.addEventListener(ev, () => { this.label(); setTimeout(() => window.dispatchEvent(new Event('resize')), 120); }));
        this.label();
    },
};

// =====================================================================================================
// [JUMP]  Debug › Jump to mission (host only): start the job over and fast-forward to any point in the story — every
//         mission before it done (layouts staked, LOD cleared, silt fence up, roads / cable / piles / trees / panels
//         built), that mission handed out. Forward or backward. Online, the crew re-syncs onto the same world.
// =====================================================================================================
const Jump = {
    KEY: 'surveySim.jump',
    STORY: ['T1', 'T2', 'T3', 'T6', 'T8', 'T9', 'T10', 'T7', 'T11', 'T12', 'T13', 'T14', 'T15'],
    armed: null, armedUntil: 0, pend: null,
    // where the story is right now: the first story mission that isn't done ('END' = all done)
    at() { const t = this.STORY.find(id => { const q = TaskManager.get(id); return q && q.status !== 'completed'; }); return t || 'END'; },
    list() { return this.STORY.map(id => ({ id, title: (TaskManager.get(id) || {}).title || id })).concat([{ id: 'END', title: 'Job finished (everything built)' }]); },
    render() {
        const el = $('jump-list'); if (!el) return;
        const cur = this.at(), now = performance.now();
        el.innerHTML = this.list().map((m, i) => `<button class="jump-row${m.id === cur ? ' cur' : ''}${this.armed === m.id && now < this.armedUntil ? ' armed' : ''}" data-jump="${m.id}"><b>${m.id === 'END' ? '✓' : i + 1}</b><span>${escHTML(m.title)}</span><em>${m.id === cur ? 'YOU ARE HERE' : this.armed === m.id && now < this.armedUntil ? 'TAP AGAIN' : ''}</em></button>`).join('');
        el.querySelectorAll('[data-jump]').forEach(b => b.addEventListener('click', e => { e.stopPropagation(); this.pick(b.dataset.jump); }));
    },
    toggle() { const el = $('jump-list'); if (!el) return; el.hidden = !el.hidden; if (!el.hidden) this.render(); },
    pick(id) {
        if (!Owner.is) { showToast('Host only.'); return; }
        if (Net.helping()) { showToast(`Only the crew lead (${Net.leadName()}) can move the job.`); return; }
        const now = performance.now();
        if (this.armed !== id || now > this.armedUntil) { this.armed = id; this.armedUntil = now + 4000; this.render(); showToast('Tap it again to rebuild the job site at that mission.'); return; }
        this.armed = null;
        try { window.sessionStorage.setItem(this.KEY, JSON.stringify({ id, solo: !(Net.on && Net.rc && Net.rc !== 'TEST'), t: Date.now() })); } catch (e) { showToast('Could not save the jump (storage blocked).'); return; }
        showToast('⏩ Rebuilding the job site…');
        Save.wipe(true);
    },
    // after the reload (the old save is gone): what to fast-forward to
    take() {
        try { const v = JSON.parse(window.sessionStorage.getItem(this.KEY) || 'null'); window.sessionStorage.removeItem(this.KEY); if (v && v.id && Date.now() - v.t < 120000) return v; } catch (e) { /* storage blocked */ }
        return null;
    },
    // one mission, done the way a real crew would have left it
    finish(id) {
        const TM = TaskManager, t = TM.get(id); if (!t || t.status === 'completed') return;
        if (!t.points.length) TM.generateLayout(t);
        t.stakedFlags = t.points.map(() => true); t.vertexStakes = t.points.map(() => null);
        t.status = 'completed'; t.built = true; if (t.rule.deliver) t.talked = true;
        if (t.rule.code === 'LOD' && t.points.length > 2) Dozer.clear(TM.lodPoly(t), false);
        if (t.rule.code === 'SILT' && t.points.length > 1) SiltFence.build(t.anchors ? [t.anchors.a, ...t.points, t.anchors.b] : t.points, t.type === 'boundary', false);
        (Build.STAGES[id] || []).forEach(st => Build.run(st, false));
        TM.refresh();
    },
    apply(id) {
        const TM = TaskManager, n = id === 'END' ? this.STORY.length : this.STORY.indexOf(id);
        if (n < 0) return;
        for (let k = 0; k < n; k++) { try { this.finish(this.STORY[k]); } catch (e) { console.warn('jump', this.STORY[k], e); } }
        TM.active = null; TM.justCompleted = null; TM.refresh();
        let t = id === 'END' ? null : TM.get(id);
        if (t && t.id === 'T14' && !Trees.targets().length) { this.finish('T14'); t = TM.get('T15'); }      // no trees in the rows on this site
        if (t && TM.activate(t)) TM.speech = `Next up: <b>${t.title}</b>. ` + (t.brief || '');
        TM.updateHud(); Save.touch(); Save.flush();
        const label = t ? `${this.STORY.indexOf(t.id) + 1}. ${t.title}` : 'the finished job';
        setTimeout(() => showToast(`⏩ Jumped to ${label} — everything before it is done.`), 1500);
    },
};

