$('dev-look').addEventListener('click', () => { toggleDevMenu(false); Title.reopen('look'); });
$('dev-leave').addEventListener('click', () => { toggleDevMenu(false); Title.leaveSession(); });
scene.updateMatrixWorld(true);
animate();

TouchUI.init();

